class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)
        suffix = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] | nums[i]
        best = 0
        pre = 0
        for i in range(n):
            val = pre | (nums[i] << k) | suffix[i + 1]
            if val > best:
                best = val
            pre |= nums[i]
        return best
