class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        n = len(s)
        ans = 1
        left = 0
        count = 0
        for i in range(1, n):
            if s[i] == s[i-1]:
                count += 1
            while count > 1:
                if s[left] == s[left+1]:
                    count -= 1
                left += 1
            ans = max(ans, i - left + 1)
        return ans
