class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can(s, target):
            if not s:
                return target == 0
            if target < 0:
                return False
            for k in range(1, len(s) + 1):
                v = int(s[:k])
                if v > target:
                    break
                if can(s[k:], target - v):
                    return True
            return False

        total = 0
        for i in range(1, n + 1):
            if can(str(i * i), i):
                total += i * i
        return total
class Solution:
