class Solution:
    def paintWalls(self, cost: List[int], time: List[int]) -> int:
        n = len(cost)
        INF = float('inf')
        dp = [0] + [INF] * n
        for c, t in zip(cost, time):
            for j in range(n, 0, -1):
                prev = j - t - 1
                if prev < 0:
                    prev = 0
                v = dp[prev] + c
                if v < dp[j]:
                    dp[j] = v
        return dp[n]
