class Solution:
    def longestEqualSubarray(self, nums: List[int], k: int) -> int:
        groups = defaultdict(list)
        for i, v in enumerate(nums):
            groups[v].append(i)
        best = 0
        for pos in groups.values():
            l = 0
            for r in range(len(pos)):
                while pos[r] - pos[l] - (r - l) > k:
                    l += 1
                if r - l + 1 > best:
                    best = r - l + 1
        return best
