class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        adj = [0] * n
        for i in range(n):
            for j in range(n):
                if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                    adj[i] |= 1 << j
        full = (1 << n) - 1
        dp = [[0] * n for _ in range(1 << n)]
        for j in range(n):
            dp[1 << j][j] = 1
        for mask in range(1, 1 << n):
            row = dp[mask]
            for j in range(n):
                v = row[j]
                if not v:
                    continue
                cand = adj[j] & ~mask
                while cand:
                    lb = cand & -cand
                    k = lb.bit_length() - 1
                    nm = mask | lb
                    dp[nm][k] = (dp[nm][k] + v) % MOD
                    cand ^= lb
        return sum(dp[full]) % MOD
