class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            seen = [False] * (n + 3)
            cur = -1
            for j in range(i, n):
                x = nums[j]
                if not seen[x]:
                    cur += 1
                    if seen[x - 1]:
                        cur -= 1
                    if seen[x + 1]:
                        cur -= 1
                    seen[x] = True
                total += cur
        return total
