class Solution:
    def continuousSubarrays(self, nums: List[int]) -> int:
        mx = deque()
        mn = deque()
        left = 0
        ans = 0
        for r, v in enumerate(nums):
            while mx and nums[mx[-1]] <= v:
                mx.pop()
            mx.append(r)
            while mn and nums[mn[-1]] >= v:
                mn.pop()
            mn.append(r)
            while nums[mx[0]] - nums[mn[0]] > 2:
                left += 1
                if mx[0] < left:
                    mx.popleft()
                if mn[0] < left:
                    mn.popleft()
            ans += r - left + 1
        return ans
