class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        best = -1
        for i in range(n - 1):
            if nums[i + 1] - nums[i] != 1:
                continue
            j = i + 1
            # extend while differences alternate
            while j + 1 < n:
                expected = 1 if (j + 1 - i) % 2 == 1 else -1
                if nums[j + 1] - nums[j] == expected:
                    j += 1
                else:
                    break
            best = max(best, j - i + 1)
        return best
