class Solution:
    def minimumString(self, a: str, b: str, c: str) -> str:
        def merge(s, t):
            if t in s:
                return s
            for k in range(min(len(s), len(t)), -1, -1):
                if s.endswith(t[:k]):
                    return s + t[k:]
            return s + t
        best = None
        for x, y, z in permutations([a, b, c]):
            r = merge(merge(x, y), z)
            if best is None or (len(r), r) < (len(best), best):
                best = r
        return best
