class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        n = len(s)
        INF = float('inf')
        cost = [[INF] * n for _ in range(n)]
        for d in range(1, n // 2 + 1):
            pc = [[0] * n for _ in range(n)]
            gap = d
            while gap < n:
                for a in range(n - gap):
                    b = a + gap
                    inner = pc[a + d][b - d] if gap >= 2 * d else 0
                    pc[a][b] = inner + (1 if s[a] != s[b] else 0)
                gap += d
            L = 2 * d
            while L <= n:
                for i in range(n - L + 1):
                    j = i + L - 1
                    base = j - d + 1
                    total = 0
                    for r in range(d):
                        total += pc[i + r][base + r]
                    if total < cost[i][j]:
                        cost[i][j] = total
                L += d
        # dp
        prev = [INF] * (n + 1)
        prev[0] = 0
        for t in range(1, k + 1):
            cur = [INF] * (n + 1)
            for j in range(2 * t, n + 1):
                best = INF
                for i in range(2 * (t - 1), j - 1):
                    if prev[i] == INF:
                        continue
                    c = cost[i][j - 1]
                    v = prev[i] + c
                    if v < best:
                        best = v
                cur[j] = best
            prev = cur
        return prev[n]
