class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        fb = set(forbidden)
        maxlen = max(len(f) for f in forbidden)
        left = 0
        best = 0
        n = len(word)
        for right in range(n):
            for L in range(1, maxlen + 1):
                start = right - L + 1
                if start < left:
                    break
                if word[start:right + 1] in fb:
                    left = start + 1
                    break
            cur = right - left + 1
            if cur > best:
                best = cur
        return best
