class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        fs = set(forbidden)
        maxlen = max(len(f) for f in forbidden)
        left = 0
        best = 0
        n = len(word)
        for i in range(n):
            lo = max(left, i - maxlen + 1)
            for j in range(i, lo - 1, -1):
                if word[j:i+1] in fs:
                    left = j + 1
                    break
            if i - left + 1 > best:
                best = i - left + 1
        return best

