    def maxScore(self, nums: List[int], x: int) -> int:
        NEG = float('-inf')
        best = [NEG, NEG]
        best[nums[0] % 2] = nums[0]
        for v in nums[1:]:
            p = v % 2
            cur = v + max(best[p], best[1 - p] - x)
            if cur > best[p]:
                best[p] = cur
        return max(best)
