class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        S = t + '#' + s + s[:-1]
        L = len(S)
        z = [0] * L
        l = r = 0
        for i in range(1, L):
            if i < r:
                zi = min(r - i, z[i - l])
            else:
                zi = 0
            while i + zi < L and S[zi] == S[i + zi]:
                zi += 1
            z[i] = zi
            if i + zi > r:
                l, r = i, i + zi
        cnt = 0
        c0 = 0
        base = n + 1
        for i in range(n):
            if z[base + i] >= n:
                cnt += 1
                if i == 0:
                    c0 = 1
        if cnt == 0:
            return 0
        inv = pow(n, MOD - 2, MOD)
        pk = pow(n - 1, k, MOD)
        sign = 1 if k % 2 == 0 else MOD - 1
        f = (pk + (n - 1) * sign) % MOD * inv % MOD
        g = (pk - sign) % MOD * inv % MOD
        return (c0 * f + (cnt - c0) * g) % MOD
class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
