class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # find match positions of t in s+s[:-1]
        p = t + '#' + s + s[:-1]
        m = len(p)
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j and p[i] != p[j]:
                j = pi[j - 1]
            if p[i] == p[j]:
                j += 1
            pi[i] = j
        cnt0 = 0
        cnt_other = 0
        # position in s+s[:-1] start index = i - 2n
        for i in range(2 * n, m):
            if pi[i] == n:
                start = i - 2 * n
                if start == 0:
                    cnt0 += 1
                else:
                    cnt_other += 1
        if cnt0 == 0 and cnt_other == 0:
            return 0
        inv_n = pow(n, MOD - 2, MOD)
        a = pow(n - 1, k, MOD)
        sign = 1 if k % 2 == 0 else MOD - 1
        f0 = (a + (n - 1) * sign) % MOD * inv_n % MOD
        f1 = (a - sign) % MOD * inv_n % MOD
        return (cnt0 * f0 + cnt_other * f1) % MOD

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1
        cnt = [0] * 64
        for x in nums:
            cnt[x.bit_length() - 1] += 1
        ans = 0
        i = 0
        while i < 62:
            if (target >> i) & 1:
                if cnt[i] > 0:
                    cnt[i] -= 1
                else:
                    j = i + 1
                    while j < 63 and cnt[j] == 0:
                        j += 1
                    if j >= 63:
                        return -1
                    ans += j - i
                    cnt[j] -= 1
                    for k in range(i, j):
                        cnt[k] += 1
                    # the extra 2^i piece is used for this bit
            cnt[i + 1] += cnt[i] // 2
            i += 1
        return ans
