class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1
        cnt = [0] * 64
        for x in nums:
            cnt[x.bit_length() - 1] += 1
        acc = 0
        ops = 0
        for i in range(62):
            acc += cnt[i] << i
            if (target >> i) & 1:
                if acc >= (1 << i):
                    acc -= (1 << i)
                else:
                    j = i + 1
                    while cnt[j] == 0:
                        j += 1
                    ops += j - i
                    cnt[j] -= 1
                    for k in range(i + 1, j):
                        cnt[k] += 1
                    acc += (1 << i)
        return ops

