class Solution:
    def getMaxFunctionValue(self, receiver: List[int], k: int) -> int:
        n = len(receiver)
        nxt = receiver[:]
        sm = receiver[:]
        pos = list(range(n))
        total = list(range(n))
        while k:
            if k & 1:
                total = [t + sm[p] for t, p in zip(total, pos)]
                pos = [nxt[p] for p in pos]
            k >>= 1
            if k:
                sm = [s + sm[q] for s, q in zip(sm, nxt)]
                nxt = [nxt[q] for q in nxt]
        return max(total)
