    def maximumSumOfHeights(self, maxHeights: List[int]) -> int:
        n = len(maxHeights)
        left = [0] * n
        st = []
        for i in range(n):
            while st and maxHeights[st[-1]] >= maxHeights[i]:
                st.pop()
            if st:
                j = st[-1]
                left[i] = left[j] + maxHeights[i] * (i - j)
            else:
                left[i] = maxHeights[i] * (i + 1)
            st.append(i)
