    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        n = len(nums)
        total = sum(nums)
        q, r = divmod(target, total)
        if r == 0:
            return q * n
        arr = nums + nums
        best = float('inf')
        left = 0
        s = 0
        for right in range(len(arr)):
            s += arr[right]
            while s > r and left <= right:
                s -= arr[left]
                left += 1
            if s == r:
                best = min(best, right - left + 1)
        if best == float('inf'):
            return -1
        return q * n + best
