    def maxSum(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        cnt = [0] * 31
        for x in nums:
            for b in range(31):
                if x >> b & 1:
                    cnt[b] += 1
        ans = 0
        for _ in range(k):
