        cnt = Counter(nums)
        freq = Counter(cnt.values())
        m = min(freq)
        for k in range(m, 0, -1):
            total = 0
            ok = True
            for c, mult in freq.items():
                q, r = divmod(c, k + 1)
                if r == 0:
                    total += q * mult
                elif k - r <= q:
                    total += (q + 1) * mult
                else:
                    ok = False
                    break
            if ok:
                return total
        return len(nums)
