class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        MOD = 10**9 + 7
        a1 = (a >> n) << n
        b1 = (b >> n) << n
        for i in range(n - 1, -1, -1):
            ab = (a >> i) & 1
            bb = (b >> i) & 1
            if ab == bb:
                a1 |= 1 << i
                b1 |= 1 << i
            else:
                if a1 <= b1:
                    a1 |= 1 << i
                else:
                    b1 |= 1 << i
        return (a1 % MOD) * (b1 % MOD) % MOD
