            bb = (b >> i) & 1
            if ba == bb:
                x |= 1 << i
                y |= 1 << i
            else:
                if x <= y:
                    x |= 1 << i
                else:
                    y |= 1 << i
        return (x % MOD) * (y % MOD) % MOD

