class Solution:
    def maxFrequencyScore(self, nums: List[int], k: int) -> int:
        a = sorted(nums)
        n = len(a)
        pre = [0] * (n + 1)
        for i, x in enumerate(a):
            pre[i + 1] = pre[i] + x

        def cost(l, r):
            m = (l + r) // 2
            left = a[m] * (m - l) - (pre[m] - pre[l])
            right = (pre[r + 1] - pre[m + 1]) - a[m] * (r - m)
            return left + right

        ans = 0
        l = 0
        for r in range(n):
            while cost(l, r) > k:
                l += 1
            ans = max(ans, r - l + 1)
        return ans
