class Solution:
    def canMakePalindromeQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        n = len(s)
        m = n // 2
        A = s[:m]
        B = s[m:][::-1]
        pa = [[0] * 26]
        pb = [[0] * 26]
        pd = [0]
        for i in range(m):
            x = pa[-1][:]
            x[ord(A[i]) - 97] += 1
            pa.append(x)
            y = pb[-1][:]
            y[ord(B[i]) - 97] += 1
            pb.append(y)
            pd.append(pd[-1] + (A[i] != B[i]))

        def cnt(P, l, r):
            if l > r:
                return [0] * 26
            return [x - y for x, y in zip(P[r + 1], P[l])]

        def mism(l, r):
            if l > r:
                return 0
            return pd[r + 1] - pd[l]

        def partial(PA, PB, a, b, c, d):
            # a < c <= b < d ; PA's interval [a,b], PB's interval [c,d]
            x = cnt(PA, a, b)
            y = cnt(PB, a, c - 1)
            for i in range(26):
                if x[i] < y[i]:
                    return False
            x = cnt(PB, c, d)
            y = cnt(PA, b + 1, d)
            for i in range(26):
                if x[i] < y[i]:
                    return False
            return cnt(PA, a, d) == cnt(PB, a, d)

        res = []
        for qa, qb, qc, qd in queries:
            a, b = qa, qb
            c, d = n - 1 - qd, n - 1 - qc
            lo = min(a, c)
            hi = max(b, d)
            if mism(0, lo - 1) or mism(hi + 1, m - 1):
                res.append(False)
                continue
            if b < c or d < a:
                if b < c:
                    ok = mism(b + 1, c - 1) == 0
                else:
                    ok = mism(d + 1, a - 1) == 0
                ok = ok and cnt(pa, a, b) == cnt(pb, a, b) and cnt(pa, c, d) == cnt(pb, c, d)
                res.append(ok)
            elif a <= c and d <= b:
                res.append(cnt(pa, a, b) == cnt(pb, a, b))
            elif c <= a and b <= d:
                res.append(cnt(pa, c, d) == cnt(pb, c, d))
            elif a < c:
                res.append(partial(pa, pb, a, b, c, d))
            else:
                res.append(partial(pb, pa, c, d, a, b))
        return res
