class Solution:
    def canMakePalindromeQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        n = len(s)
        m = n // 2
        A = s[:m]
        B = s[m:][::-1]
        pA = [[0] * 26]
        pB = [[0] * 26]
        pd = [0] * (m + 1)
        for i in range(m):
            r = pA[-1][:]
            r[ord(A[i]) - 97] += 1
            pA.append(r)
            r = pB[-1][:]
            r[ord(B[i]) - 97] += 1
            pB.append(r)
            pd[i + 1] = pd[i] + (A[i] != B[i])

        def cnt(P, l, r):
            if l > r:
                return [0] * 26
            x = P[r + 1]; y = P[l]
            return [x[k] - y[k] for k in range(26)]

        def mis(l, r):
            if l > r:
                return 0
            return pd[r + 1] - pd[l]

        res = []
        for a, b, c, d in queries:
            c2, d2 = n - 1 - d, n - 1 - c
            PA, PB = pA, pB
            if a > c2:
                a, b, c2, d2 = c2, d2, a, b
                PA, PB = pB, pA
            if b < c2:
                ok = (mis(0, a - 1) == 0 and mis(b + 1, c2 - 1) == 0 and mis(d2 + 1, m - 1) == 0
                      and cnt(PA, a, b) == cnt(PB, a, b) and cnt(PA, c2, d2) == cnt(PB, c2, d2))
            elif d2 <= b:
                ok = (mis(0, a - 1) == 0 and mis(b + 1, m - 1) == 0
                      and cnt(PA, a, b) == cnt(PB, a, b))
            else:
                ok = mis(0, a - 1) == 0 and mis(d2 + 1, m - 1) == 0
                if ok:
                    x = cnt(PA, a, b)
                    y = cnt(PB, a, c2 - 1)
                    r1 = [x[k] - y[k] for k in range(26)]
                    x = cnt(PB, c2, d2)
                    y = cnt(PA, b + 1, d2)
                    r2 = [x[k] - y[k] for k in range(26)]
                    ok = min(r1) >= 0 and min(r2) >= 0 and r1 == r2
            res.append(ok)
        return res

