            ps = str(prefix)
            if length % 2 == 0:
                return int(ps + ps[::-1])
            else:
                return int(ps + ps[:-1][::-1])

        h = (L + 1) // 2
        p0 = int(s[:h])
        for p in (p0 - 1, p0, p0 + 1):
