        below = max([c for c in valid if c <= m], default=None)
        above = min([c for c in valid if c >= m], default=None)
        best = None
        for c in (below, above):
            if c is None:
                continue
            cost = sum(abs(x - c) for x in nums)
            if best is None or cost < best:
