            if w < d[a][b]:
                d[a][b] = w
        for k in range(26):
            dk = d[k]
            for i in range(26):
                di = d[i]
                dik = di[k]
                if dik == INF:
                    continue
                for j in range(26):
                    v = dik + dk[j]
                    if v < di[j]:
                        di[j] = v
        total = 0
        for (s, t), cnt in Counter(zip(source, target)).items():
            if s == t:
                continue
            v = d[ord(s)-97][ord(t)-97]
            if v == INF:
                return -1
            total += v * cnt
        return total
