class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x <= y:
            return y - x
        limit = max(x, y) + 20
        dist = {x: 0}
        q = deque([x])
        while q:
            cur = q.popleft()
            d = dist[cur]
            if cur == y:
                return d
            nxt = []
            if cur > 0:
                nxt.append(cur - 1)
            if cur + 1 <= limit:
                nxt.append(cur + 1)
            if cur % 11 == 0:
                nxt.append(cur // 11)
            if cur % 5 == 0:
                nxt.append(cur // 5)
            for n in nxt:
                if n not in dist:
                    dist[n] = d + 1
                    q.append(n)
        return abs(x - y)
