        ans = 0
        mask = 0
        n = len(nums)
        for b in range(29, -1, -1):
            mask |= 1 << b
            target = ans  # bits allowed (bit b must be 0)
            cnt = 0
            cur = mask
            for x in nums:
                cur &= x & mask
                if cur & ~target:
                    cnt += 1
                else:
