class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        # Comparison sequence: 1 = increase, 0 = equal, -1 = decrease
        s = [(nums[i+1] > nums[i]) - (nums[i+1] < nums[i]) for i in range(len(nums)-1)]
        m = len(pattern)

        # KMP failure function for the pattern
        fail = [0] * m
        k = 0
        for i in range(1, m):
            while k and pattern[i] != pattern[k]:
                k = fail[k-1]
            if pattern[i] == pattern[k]:
                k += 1
            fail[i] = k

        # Scan the comparison sequence and count full matches
        count = 0
        k = 0
        for x in s:
            while k and x != pattern[k]:
                k = fail[k-1]
            if x == pattern[k]:
                k += 1
            if k == m:
                count += 1
                k = fail[k-1]
        return count
