class Solution:
    def maximumStrength(self, nums: List[int], k: int) -> int:
        NEG = float('-inf')
        n = len(nums)
        w = [0] * (k + 1)
        for j in range(1, k + 1):
            w[j] = (k - j + 1) if j % 2 == 1 else -(k - j + 1)
        f = [NEG] * (k + 1)
        g = [NEG] * (k + 1)
        f[0] = 0
        for i, x in enumerate(nums):
            hi = min(k, i + 1)
            lo = max(1, k - (n - i))
            for j in range(hi, lo - 1, -1):
                a = g[j]
                b = f[j - 1]
                if b > a:
                    a = b
                if a == NEG:
                    continue
                v = a + w[j] * x
                g[j] = v
                if v > f[j]:
                    f[j] = v
        return f[k]
