    def maximumStrength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        NEG = float('-inf')
        fprev = [0] * (n + 1)
        for j in range(1, k + 1):
            w = (k - j + 1) if j % 2 == 1 else -(k - j + 1)
            fcur = [NEG] * (n + 1)
            g = NEG
            best = NEG
            for i in range(1, n + 1):
                p = fprev[i - 1]
                if p > g:
                    g = p
                g = g + w * nums[i - 1]
                if g > best:
                    best = g
                fcur[i] = best
            fprev = fcur
        return fprev[n]
