        g = [NEG] * (k + 1)
        f[0] = 0
        for i, x in enumerate(nums):
            top = i + 1 if i + 1 < k else k
            for j in range(top, 0, -1):
                a = g[j]
                b = f[j - 1]
                if b > a:
                    a = b
                a += w[j] * x
                g[j] = a
                if a > f[j]:
                    f[j] = a
        return f[k]

