class Solution:
    def minimumMoves(self, nums: List[int], k: int, maxChanges: int) -> int:
        n = len(nums)
        # max consecutive ones capped at 3
        c = 0
        run = 0
        for x in nums:
            if x == 1:
                run += 1
                c = max(c, min(run, 3))
            else:
                run = 0
        if c >= k:
            return k - 1
        if c + maxChanges >= k:
            return max(c - 1, 0) + 2 * (k - c)
        pos = [i for i, x in enumerate(nums) if x == 1]
        m = len(pos)
        S = [0] * (m + 1)
        for i, p in enumerate(pos):
            S[i + 1] = S[i] + p
        need = k - maxChanges
        best = float('inf')
        for l in range(0, m - need + 1):
            r = l + need - 1
            mid = (l + r) // 2
            pm = pos[mid]
            cost = pm * (mid - l) - (S[mid] - S[l]) + (S[r + 1] - S[mid + 1]) - pm * (r - mid)
            if cost < best:
                best = cost
        return best + 2 * maxChanges
