class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        n = len(nums)
        INF = float('inf')
        prev = [INF] * (n + 1)
        prev[0] = 0
        for t in andValues:
            cur = [INF] * (n + 1)
            groups = []  # list of [val, minprev], ordered from oldest start to newest
            for r in range(n):
                x = nums[r]
                new = []
                for v, mp in groups:
                    nv = v & x
                    if new and new[-1][0] == nv:
                        if mp < new[-1][1]:
                            new[-1][1] = mp
                    else:
                        new.append([nv, mp])
                p = prev[r]
                if new and new[-1][0] == x:
                    if p < new[-1][1]:
                        new[-1][1] = p
                else:
                    new.append([x, p])
                groups = new
                for v, mp in groups:
                    if v == t:
                        if mp < INF:
                            cur[r + 1] = x + mp
                        break
            prev = cur
        return prev[n] if prev[n] < INF else -1
