class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        coins = sorted(set(coins))
        filtered = []
        for c in coins:
            if all(c % f != 0 for f in filtered):
                filtered.append(c)
        coins = filtered
        n = len(coins)
        hi = min(coins) * k
        lcms = [1] * (1 << n)
        terms = []
        for mask in range(1, 1 << n):
            low = mask & (-mask)
            i = low.bit_length() - 1
            prev = lcms[mask ^ low]
            if prev > hi:
                lcms[mask] = hi + 1
                continue
            c = coins[i]
            l = prev // gcd(prev, c) * c
            lcms[mask] = l
            if l <= hi:
                sign = 1 if bin(mask).count('1') % 2 == 1 else -1
                terms.append((l, sign))

        def count(x):
            s = 0
            for l, sg in terms:
                s += sg * (x // l)
            return s

        lo = 1
        while lo < hi:
            mid = (lo + hi) // 2
            if count(mid) >= k:
                hi = mid
            else:
                lo = mid + 1
        return lo
