        lcms = [l for l, s in subs]
        signs = [s for l, s in subs]
        pairs = list(zip(lcms, signs))

        def count(x):
            t = 0
            for l, s in pairs:
                t += s * (x // l)
            return t

        lo = 1
        while lo < hi:
            mid = (lo + hi) // 2
            if count(mid) >= k:
                hi = mid
            else:
                lo = mid + 1
        return lo
