class Solution:
    def minOperationsToMakeMedianK(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        m = n // 2
        ops = abs(nums[m] - k)
        if nums[m] > k:
            i = m - 1
            while i >= 0 and nums[i] > k:
                ops += nums[i] - k
                i -= 1
        elif nums[m] < k:
            i = m + 1
            while i < n and nums[i] < k:
                ops += k - nums[i]
                i += 1
        return ops

