class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        X, Y = xCorner, yCorner
        n = len(circles)

        def inCircle(cx, cy, x, y, r):
            return (cx - x) ** 2 + (cy - y) ** 2 <= r * r

        def touchTL(x, y, r):
            return (x <= r and y <= Y) or (abs(y - Y) <= r and x <= X)

        def touchBR(x, y, r):
            return (y <= r and x <= X) or (abs(x - X) <= r and y <= Y)

        for x, y, r in circles:
            if inCircle(0, 0, x, y, r) or inCircle(X, Y, x, y, r):
                return False

        vis = [False] * n
        for s in range(n):
            if vis[s]:
                continue
            x, y, r = circles[s]
            if not touchTL(x, y, r):
                continue
            vis[s] = True
            stack = [s]
            while stack:
                i = stack.pop()
                x1, y1, r1 = circles[i]
                if touchBR(x1, y1, r1):
                    return False
                for j in range(n):
                    if vis[j]:
                        continue
                    x2, y2, r2 = circles[j]
                    if (x1 - x2) ** 2 + (y1 - y2) ** 2 > (r1 + r2) ** 2:
                        continue
                    if x1 * r2 + x2 * r1 < (r1 + r2) * X and y1 * r2 + y2 * r1 < (r1 + r2) * Y:
                        vis[j] = True
                        stack.append(j)
        return True
