class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        X, Y = xCorner, yCorner
        n = len(circles)

        def in_circle(ox, oy, r, px, py):
            return (ox - px) ** 2 + (oy - py) ** 2 <= r * r

        def left_top(x, y, r):
            a = abs(x) <= r and 0 <= y <= Y
            b = abs(y - Y) <= r and 0 <= x <= X
            return a or b

        def right_bottom(x, y, r):
            a = abs(x - X) <= r and 0 <= y <= Y
            b = abs(y) <= r and 0 <= x <= X
            return a or b

        for x, y, r in circles:
            if in_circle(x, y, r, 0, 0) or in_circle(x, y, r, X, Y):
                return False

        def connected(i, j):
            x1, y1, r1 = circles[i]
            x2, y2, r2 = circles[j]
            if (x1 - x2) ** 2 + (y1 - y2) ** 2 > (r1 + r2) ** 2:
                return False
            return (x1 * r2 + x2 * r1 < (r1 + r2) * X and
                    y1 * r2 + y2 * r1 < (r1 + r2) * Y)

        vis = [False] * n
        for s in range(n):
            if vis[s]:
                continue
            x, y, r = circles[s]
            if not left_top(x, y, r):
                continue
            vis[s] = True
            stack = [s]
            while stack:
                i = stack.pop()
                xi, yi, ri = circles[i]
                if right_bottom(xi, yi, ri):
                    return False
                for j in range(n):
                    if not vis[j] and connected(i, j):
                        vis[j] = True
                        stack.append(j)
        return True
