        parent = list(range(n + 2))
        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
        S, E = n, n + 1
        for i, (x, y, r) in enumerate(circles):
            if x * x + y * y <= r * r:
                return False
            if (x - X) ** 2 + (y - Y) ** 2 <= r * r:
                return False
            if (x <= r and y <= Y) or (abs(y - Y) <= r and x <= X):
                union(i, S)
            if (abs(x - X) <= r and y <= Y) or (y <= r and x <= X):
                union(i, E)
        for i in range(n):
            x1, y1, r1 = circles[i]
            for j in range(i + 1, n):
                x2, y2, r2 = circles[j]
                dx = x1 - x2
                dy = y1 - y2
                rs = r1 + r2
                if dx * dx + dy * dy <= rs * rs:
                    if x1 * r2 + x2 * r1 < rs * X and y1 * r2 + y2 * r1 < rs * Y:
                        union(i, j)
        return find(S) != find(E)

