class Solution:
    def nonSpecialCount(self, l: int, r: int) -> int:
        import math
        n = math.isqrt(r)
        if n < 2:
            return r - l + 1
        sieve = bytearray([1]) * (n + 1)
        sieve[0] = sieve[1] = 0
        for i in range(2, math.isqrt(n) + 1):
            if sieve[i]:
                sieve[i*i::i] = bytearray(len(range(i*i, n + 1, i)))
        cnt = 0
        for p in range(2, n + 1):
            if sieve[p] and p * p >= l:
                cnt += 1
        return r - l + 1 - cnt
