            a = a.zfill(L)
            b = b.zfill(L)
            diff = [k for k in range(L) if a[k] != b[k]]
            if not diff:
                return True
            if len(diff) == 2:
                i, j = diff
                return a[i] == b[j] and a[j] == b[i]
            return False

