class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def ok(x, y):
            a, b = str(x), str(y)
            L = max(len(a), len(b))
            a, b = a.zfill(L), b.zfill(L)
            diff = [i for i in range(L) if a[i] != b[i]]
            if not diff:
                return True
            if len(diff) == 2:
                p, q = diff
                return a[p] == b[q] and a[q] == b[p]
            return False
        n = len(nums)
        return sum(1 for i in range(n) for j in range(i + 1, n) if ok(nums[i], nums[j]))

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        dp = [1] * (nums[0] + 1)
        for i in range(1, len(nums)):
            prev = nums[i-1]
            pre = [0] * (prev + 2)
            for a in range(prev + 1):
                pre[a+1] = (pre[a] + dp[a]) % MOD
            d = max(0, nums[i] - prev)
            ndp = [0] * (nums[i] + 1)
            for b in range(nums[i] + 1):
                hi = b - d
                if hi < 0:
                    continue
                hi = min(hi, prev)
                ndp[b] = pre[hi+1]
            dp = ndp
        return sum(dp) % MOD
