class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')
        n = len(word)
        res = 0
        for i in range(n):
            seen = set()
            cons = 0
            for j in range(i, n):
                c = word[j]
                if c in vowels:
                    seen.add(c)
                else:
                    cons += 1
                    if cons > k:
                        break
                if cons == k and len(seen) == 5:
                    res += 1
        return res
