class Solution:
    def validSubstringCount(self, word1: str, word2: str) -> int:
        need = [0] * 26
        for ch in word2:
            need[ord(ch) - 97] += 1
        missing = len(word2)
        n = len(word1)
        ans = 0
        l = 0
        w = [ord(ch) - 97 for ch in word1]
        for r in range(n):
            c = w[r]
            if need[c] > 0:
                missing -= 1
            need[c] -= 1
            while missing == 0:
                ans += n - r
                lc = w[l]
                need[lc] += 1
                if need[lc] > 0:
                    missing += 1
                l += 1
        return ans
