class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        # tab[x][c][b]: mask resulting from mapping v -> v|x for v in byte chunk c with bits b
        tab = []
        for x in range(128):
            tx = []
            for c in range(16):
                arr = [0] * 256
                base = c * 8
                for b in range(1, 256):
                    low = b & (-b)
                    t = low.bit_length() - 1
                    arr[b] = arr[b & (b - 1)] | (1 << ((base + t) | x))
                tx.append(arr)
            tab.append(tx)

        def T(mask, x):
            res = 0
            c = 0
            tx = tab[x]
            while mask:
                b = mask & 255
                if b:
                    res |= tx[c][b]
                mask >>= 8
                c += 1
            return res

        n = len(nums)
        INF = float('inf')
        first = [INF] * 128
        dp = [0] * (k + 1)
        dp[0] = 1
        for i in range(n):
            x = nums[i]
            for j in range(min(i + 1, k), 0, -1):
                if dp[j - 1]:
                    dp[j] |= T(dp[j - 1], x)
            m = dp[k]
            for v in range(128):
                if first[v] == INF and (m >> v) & 1:
                    first[v] = i

        last = [-1] * 128
        dp = [0] * (k + 1)
        dp[0] = 1
        for idx in range(n - 1, -1, -1):
            x = nums[idx]
            cnt = n - idx
            for j in range(min(cnt, k), 0, -1):
                if dp[j - 1]:
                    dp[j] |= T(dp[j - 1], x)
            m = dp[k]
            for v in range(128):
                if last[v] == -1 and (m >> v) & 1:
                    last[v] = idx

        ans = 0
        for a in range(128):
            if first[a] == INF:
                continue
            fa = first[a]
            for b in range(128):
                if last[b] > fa:
                    if a ^ b > ans:
                        ans = a ^ b
        return ans
