class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        n = len(nums)
        M = [sum(1 << v for v in range(128) if (v >> b) & 1) for b in range(7)]
        FULL = (1 << 128) - 1

        def shift(S, x):
            T = S
            for b in range(7):
                if (x >> b) & 1:
                    m = M[b]
                    T = (T & m) | (((T & ~m) & FULL) << (1 << b))
            return T

        def build(arr):
            dp = [0] * (k + 1)
            dp[0] = 1
            res = []
            for i, x in enumerate(arr):
                for j in range(min(i + 1, k), 0, -1):
                    if dp[j - 1]:
                        dp[j] |= shift(dp[j - 1], x)
                res.append(dp[k])
            return res

        L = build(nums)
        R = build(nums[::-1])[::-1]

        def vals(mask):
            return [v for v in range(128) if (mask >> v) & 1]

        cache = {}
        best = 0
        for i in range(k - 1, n - k):
            a, b = L[i], R[i + 1]
            if not a or not b:
                continue
            key = (a, b)
            if key in cache:
                continue
            va, vb = vals(a), vals(b)
            cur = 0
            for p in va:
                for q in vb:
                    t = p ^ q
                    if t > cur:
                        cur = t
            cache[key] = cur
            if cur > best:
                best = cur
        return best
class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def compute(arr):
            res = [None] * len(arr)
            dp = [set() for _ in range(k + 1)]
            dp[0].add(0)
            for i, num in enumerate(arr):
                top = min(k, i + 1)
                for j in range(top, 0, -1):
                    if dp[j - 1]:
                        dp[j] |= {v | num for v in dp[j - 1]}
                res[i] = frozenset(dp[k])
            return res

        pre = compute(nums)
        sufr = compute(nums[::-1])
        suf = [None] * n
        for i in range(n):
            suf[i] = sufr[n - 1 - i]
        best = 0
        prevA = None
        prevB = None
        for i in range(k - 1, n - k):
            A = pre[i]
            B = suf[i + 1]
            if A == prevA and B == prevB:
                continue
            prevA, prevB = A, B
            if not A or not B:
                continue
            for a in A:
                for b in B:
                    x = a ^ b
                    if x > best:
                        best = x
            if best == 127:
                return best
        return best
