class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def build(arr):
            res = [None] * n
            dp = [set() for _ in range(k + 1)]
            dp[0].add(0)
            for i, x in enumerate(arr):
                top = min(i + 1, k)
                for j in range(top, 0, -1):
                    prev = dp[j - 1]
                    if prev:
                        dp[j].update(v | x for v in prev)
                if i >= k - 1:
                    res[i] = frozenset(dp[k])
            return res

        pre = build(nums)
        sufr = build(nums[::-1])
        # suf[i] = sets for nums[i..n-1] -> sufr[n-1-i]
        ans = 0
        cache = set()
        for i in range(k - 1, n - k):
            A = pre[i]
            B = sufr[n - 1 - (i + 1)]
            key = (A, B)
            if key in cache:
                continue
            cache.add(key)
            Bl = list(B)
            for a in A:
                for b in Bl:
                    v = a ^ b
                    if v > ans:
                        ans = v
            if ans == 127:
                return ans
        return ans

