class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        n, m = len(word1), len(word2)
        suf = [m] * (n + 1)
        j = m
        for i in range(n - 1, -1, -1):
            if j > 0 and word1[i] == word2[j - 1]:
                j -= 1
            suf[i] = j
        res = []
        used = False
        j = 0
        for i in range(n):
            if j == m:
                break
            if word1[i] == word2[j]:
                res.append(i)
                j += 1
            elif not used and suf[i + 1] <= j + 1:
                used = True
                res.append(i)
                j += 1
        if j < m:
            return []
        return res
