from operator import add

class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        tcols = [list(col) for col in zip(*travelScore)]
        dp = [0] * n
        for i in range(k):
            ss = stayScore[i]
            new = [0] * n
            for d in range(n):
                best = max(map(add, dp, tcols[d]))
                s = dp[d] + ss[d]
                new[d] = s if s > best else best
            dp = new
        return max(dp)
class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        dp = [0] * n
        cols = [list(col) for col in zip(*travelScore)]  # cols[d][c] = travelScore[c][d]
        for i in range(k):
