class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = max(nums)
        spf = list(range(n + 1))
        r = int(n ** 0.5) + 1
        # small sieve for primes up to r
        isp = [True] * (r + 1)
        primes = []
        for i in range(2, r + 1):
            if isp[i]:
                primes.append(i)
                for j in range(i * i, r + 1, i):
                    isp[j] = False
        for p in reversed(primes):
            if p * p > n:
                continue
            start = p * p
            cnt = (n - start) // p + 1
            spf[start::p] = [p] * cnt
        ops = 0
        bound = nums[-1]
        for k in range(len(nums) - 2, -1, -1):
            x = nums[k]
            if x <= bound:
                bound = x
            else:
                p = spf[x]
                if p < x and p <= bound:
                    ops += 1
                    bound = p
                else:
                    return -1
        return ops
