class Solution:
    def minOperations(self, nums: List[int]) -> int:
        M = max(nums)
        try:
            import numpy as np
            spf = np.zeros(M + 1, dtype=np.int32)
            i = 2
            while i * i <= M:
                if spf[i] == 0:
                    seg = spf[i*i::i]
                    mask = seg == 0
                    seg[mask] = i
                    spf[i*i::i] = seg
                i += 1
            spf = spf.tolist()
        except ImportError:
            spf = [0] * (M + 1)
            i = 2
            while i * i <= M:
                if spf[i] == 0:
                    for j in range(i * i, M + 1, i):
                        if spf[j] == 0:
                            spf[j] = i
                i += 1

        def sp(x):
            if x < 2:
                return x
            s = spf[x]
            return s if s else x

        ops = 0
        prev = float('inf')
        for i in range(len(nums) - 1, -1, -1):
            x = nums[i]
            if x <= prev:
                prev = x
            else:
                y = sp(x)
                if y > prev:
                    return -1
                ops += 1
                prev = y
        return ops

