class Solution:
    def subsequencePairCount(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        M = max(nums)
        G = [[gcd(a, b) for b in range(M + 1)] for a in range(M + 1)]
        dp = {(0, 0): 1}
        for x in nums:
            new = dict(dp)
            for (a, b), c in dp.items():
                k1 = (G[a][x], b)
                new[k1] = (new.get(k1, 0) + c) % MOD
                k2 = (a, G[b][x])
                new[k2] = (new.get(k2, 0) + c) % MOD
            dp = new
        ans = 0
        for g in range(1, M + 1):
            ans += dp.get((g, g), 0)
        return ans % MOD
