class Solution:
    def subsequencePairCount(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        M = max(nums)
        freq = [0] * (M + 1)
        for v in nums:
            freq[v] += 1
        cnt = [0] * (M + 1)
        for d in range(1, M + 1):
            s = 0
            for k in range(d, M + 1, d):
                s += freq[k]
            cnt[d] = s
        # mobius
        mu = [1] * (M + 1)
        is_comp = [False] * (M + 1)
        primes = []
        mu[0] = 0
        for i in range(2, M + 1):
            if not is_comp[i]:
                primes.append(i)
                mu[i] = -1
            for p in primes:
                if i * p > M:
                    break
                is_comp[i * p] = True
                if i % p == 0:
                    mu[i * p] = 0
                    break
                mu[i * p] = -mu[i]
        n = len(nums)
        p2 = [pow(2, k, MOD) for k in range(n + 1)]
        p3 = [pow(3, k, MOD) for k in range(n + 1)]

        def F(a, b):
            ca, cb = cnt[a], cnt[b]
            L = a * b // gcd(a, b)
            c = cnt[L] if L <= M else 0
            x = ca - c
            y = cb - c
            return (p3[c] * p2[x + y] - p2[cb] - p2[ca] + 1) % MOD

        ans = 0
        for g in range(1, M + 1):
            if cnt[g] == 0:
                continue
            lim = M // g
            tot = 0
            for i in range(1, lim + 1):
                if mu[i] == 0:
                    continue
                a = g * i
                if cnt[a] == 0:
                    continue
                for j in range(1, lim + 1):
                    if mu[j] == 0:
                        continue
                    b = g * j
                    if cnt[b] == 0:
                        continue
                    tot += mu[i] * mu[j] * F(a, b)
            ans = (ans + tot) % MOD
        return ans % MOD
