class Solution:
    def subsequencePairCount(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        M = max(nums)
        freq = [0] * (M + 1)
        for x in nums:
            freq[x] += 1
        cnt = [0] * (M + 1)
        for d in range(1, M + 1):
            s = 0
            for m in range(d, M + 1, d):
                s += freq[m]
            cnt[d] = s
        # mobius
        mu = [1] * (M + 1)
        is_comp = [False] * (M + 1)
        primes = []
        mu[0] = 0
        for i in range(2, M + 1):
            if not is_comp[i]:
                primes.append(i)
                mu[i] = -1
            for p in primes:
                if i * p > M:
                    break
                is_comp[i * p] = True
                if i % p == 0:
                    mu[i * p] = 0
                    break
                mu[i * p] = -mu[i]
        n = len(nums)
        p2 = [1] * (n + 1)
        p3 = [1] * (n + 1)
        for i in range(1, n + 1):
            p2[i] = p2[i - 1] * 2 % MOD
            p3[i] = p3[i - 1] * 3 % MOD

        def F(a, b):
            l = a * b // gcd(a, b)
            c = cnt[l] if l <= M else 0
            ca, cb = cnt[a], cnt[b]
            return (p3[c] * p2[ca - c] * p2[cb - c] - p2[ca] - p2[cb] + 1) % MOD

        ans = 0
        for g in range(1, M + 1):
            if cnt[g] < 2:
                continue
            k = M // g
            for i in range(1, k + 1):
                if mu[i] == 0 or cnt[g * i] == 0:
                    continue
                for j in range(1, k + 1):
                    if mu[j] == 0 or cnt[g * j] == 0:
                        continue
                    ans += mu[i] * mu[j] * F(g * i, g * j)
            ans %= MOD
        return ans % MOD

