class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        def compute(pairs, rates):
            g = defaultdict(list)
            for (a, b), r in zip(pairs, rates):
                g[a].append((b, r))
                g[b].append((a, 1.0 / r))
            amt = {initialCurrency: 1.0}
            stack = [initialCurrency]
            while stack:
                u = stack.pop()
                for v, r in g[u]:
                    if v not in amt:
                        amt[v] = amt[u] * r
                        stack.append(v)
            return amt

        a1 = compute(pairs1, rates1)
        a2 = compute(pairs2, rates2)
        best = 1.0
        for c, x in a1.items():
            if c in a2:
                best = max(best, x / a2[c])
        return best
