class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        total = sum(nums)
        left = 0
        res = 0
        for x in nums:
            if x == 0:
                right = total - left
                if left == right:
                    res += 2
                elif abs(left - right) == 1:
                    res += 1
            left += x
        return res
