class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        steps = [0] * (L + 1)
        for c in range(2, L + 1):
            steps[c] = 1 + steps[bin(c).count('1')]
        valid = [c for c in range(1, L + 1) if steps[c] <= k - 1]
        # factorials
        N = L + 1
        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i-1] * i % MOD
        inv = [1] * (N + 1)
        inv[N] = pow(fact[N], MOD - 2, MOD)
        for i in range(N, 0, -1):
            inv[i-1] = inv[i] * i % MOD
        def C(n, r):
            if r < 0 or r > n:
                return 0
            return fact[n] * inv[r] % MOD * inv[n-r] % MOD
        ans = 0
        ones = 0
        for i in range(L):
            if s[i] == '1':
                rem = L - i - 1
                for c in valid:
                    need = c - ones
                    if 0 <= need <= rem:
                        ans += C(rem, need)
                ans %= MOD
                ones += 1
        return ans % MOD

