class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        mx = max(cnt)
        best = float('inf')
        for t in range(1, mx + 1):
            states = {0: 0}  # carry -> min cost
            for i in range(26):
                c = cnt[i]
                ns = {}
                for carry, cost in states.items():
                    # target 0
                    v = cost + c
                    if ns.get(c, float('inf')) > v:
                        ns[c] = v
                    # target t
                    if c >= t:
                        nc = c - t
                        v = cost + nc
                        if ns.get(nc, float('inf')) > v:
                            ns[nc] = v
                    else:
                        need = t - c
                        v = cost + max(0, need - carry)
                        if ns.get(0, float('inf')) > v:
                            ns[0] = v
                states = ns
            r = min(states.values())
            if r < best:
                best = r
        return best
