                if i + 1 < 26 and cnt[i + 1] < t:
                    need = t - cnt[i + 1]
                    if c >= t:
                        v = min(v, max(c - t, need) + dp[i + 2])
                    v = min(v, max(c, need) + dp[i + 2])
                dp[i] = v
            if dp[0] < best:
                best = dp[0]
