                    d = cnt[i + 1]
                    if d < t:
                        exc = c - t if c >= t else c
                        de = t - d
                        cost = v + max(exc, de)
                        if cost < dp[i + 2]:
                            dp[i + 2] = cost
            if dp[26] < best:
                best = dp[26]
