class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        mx = max(cnt)
        best = len(s)
        for t in range(1, mx + 1):
            dp = [0] * 28
            for i in range(25, -1, -1):
                c = cnt[i]
                v = min(c, abs(c - t)) + dp[i + 1]
                if i + 1 < 26:
                    d = cnt[i + 1]
                    if d < t:
                        need = t - d
                        # send all to next (i becomes 0)
                        if c > 0:
                            w = max(c, need) + dp[i + 2]
                            if w < v:
                                v = w
                        if c > t:
                            w = max(c - t, need) + dp[i + 2]
                            if w < v:
                                v = w
                dp[i] = v
            if dp[0] < best:
                best = dp[0]
        return best

