class Solution:
    def findMinimumTime(self, strength: List[int], K: int) -> int:
        n = len(strength)
        full = 1 << n
        INF = float('inf')
        dp = [INF] * full
        dp[0] = 0
        for mask in range(full):
            if dp[mask] == INF:
                continue
            X = 1 + bin(mask).count('1') * K
            for i in range(n):
                if not (mask >> i) & 1:
                    t = (strength[i] + X - 1) // X
                    nm = mask | (1 << i)
                    if dp[mask] + t < dp[nm]:
                        dp[nm] = dp[mask] + t
        return dp[full - 1]
