class Solution:
    def minOperations(self, n: int, m: int) -> int:
        N = 10000
        is_prime = [True] * N
        is_prime[0] = is_prime[1] = False
        for i in range(2, 100):
            if is_prime[i]:
                for j in range(i * i, N, i):
                    is_prime[j] = False
        if is_prime[n] or is_prime[m]:
            return -1
        L = len(str(n))
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, x = heapq.heappop(pq)
            if x == m:
                return d
            if d > dist.get(x, float('inf')):
                continue
            s = list(str(x).zfill(L))
            for i in range(L):
                c = int(s[i])
                for nc in (c - 1, c + 1):
                    if 0 <= nc <= 9:
                        s[i] = str(nc)
                        y = int(''.join(s))
                        s[i] = str(c)
                        if is_prime[y]:
                            continue
                        nd = d + y
                        if nd < dist.get(y, float('inf')):
                            dist[y] = nd
                            heapq.heappush(pq, (nd, y))
        return -1
