class Solution:
    def minOperations(self, n: int, m: int) -> int:
        LIM = 10000
        sieve = [True] * LIM
        sieve[0] = sieve[1] = False
        for i in range(2, 100):
            if sieve[i]:
                for j in range(i * i, LIM, i):
                    sieve[j] = False
        if sieve[n] or sieve[m]:
            return -1
        k = len(str(n))
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, u = heapq.heappop(pq)
            if u == m:
                return d
            if d > dist.get(u, float('inf')):
                continue
            s = list(str(u).zfill(k))
            for i in range(k):
                c = int(s[i])
                for nc in (c - 1, c + 1):
                    if 0 <= nc <= 9:
                        t = s[:]
                        t[i] = str(nc)
                        v = int("".join(t))
                        if sieve[v]:
                            continue
                        nd = d + v
                        if nd < dist.get(v, float('inf')):
                            dist[v] = nd
                            heapq.heappush(pq, (nd, v))
        return -1

