    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])
        prev = [[0]*16 for _ in range(n)]
        for i in range(m):
            cur = [None]*n
            row = grid[i]
            for j in range(n):
                v = row[j]
                arr = [0]*16
                if i == 0 and j == 0:
                    arr[v] = 1
                else:
                    up = prev[j] if i > 0 else None
                    left = cur[j-1] if j > 0 else None
                    if up is not None and left is not None:
                        for p in range(16):
                            arr[p ^ v] = (up[p] + left[p]) % MOD
                    elif up is not None:
                        for p in range(16):
                            arr[p ^ v] = up[p]
                    else:
                        for p in range(16):
                            arr[p ^ v] = left[p]
                cur[j] = arr
            prev = cur
        return prev[n-1][k] % MOD
