class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        parent = list(range(T + 1))

        def find(x):
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                nxt = parent[x]
                parent[x] = root
                x = nxt
            return root

        big = 0
        small = []
        for num in nums:
            if num > T:
                big += 1
            else:
                small.append(num)

        for num in small:
            rn = find(num)
            for m in range(2 * num, T + 1, num):
                rm = find(m)
                if rm != rn:
                    parent[rm] = rn

        roots = set(find(num) for num in small)
        return big + len(roots)
