    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        runs = []
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append(j - i)
            i = j

        def ok(L):
            if L == 1:
                cnt = sum(1 for k, c in enumerate(s) if int(c) != k % 2)
                return min(cnt, n - cnt) <= numOps
            need = 0
            for r in runs:
                need += r // (L + 1)
                if need > numOps:
                    return False
            return True

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
