class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def f(m):
            return m * (m + 1) // 2 if m > 0 else 0

        def min_sum(arr):
            left = [-1] * n
            right = [n] * n
            st = []
            for i in range(n):
                # previous strictly smaller
                while st and arr[st[-1]] >= arr[i]:
                    right[st.pop()] = i  # next smaller-or-equal
                left[i] = st[-1] if st else -1
                st.append(i)
            total = 0
            for i in range(n):
                a = i - left[i]
                b = right[i] - i
                cnt = f(k) - f(k - a) - f(k - b) + f(k - a - b)
                total += arr[i] * cnt
            return total

        return min_sum(nums) - min_sum([-x for x in nums])
