class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def cnt(a, b):
            m = min(a, k)
            t = min(m, max(0, k - b + 1))
            res = t * b
            if m > t:
                # sum of (k - x) for x in [t, m-1]
                c = m - t
                sx = (t + m - 1) * c // 2
                res += c * k - sx
            return res

        def contrib(arr):
            # sum of minimums of subarrays with length <= k
            left = [-1] * n
            right = [n] * n
            st = []
            for i in range(n):
                while st and arr[st[-1]] >= arr[i]:
                    right[st.pop()] = i
                left[i] = st[-1] if st else -1
                st.append(i)
            total = 0
            for i in range(n):
                total += arr[i] * cnt(i - left[i], right[i] - i)
            return total

        return contrib(nums) - contrib([-x for x in nums])
