    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        m = k - 1

        def count(a, b):
            A = min(a, m + 1)
            if A <= 0:
                return 0
            c1 = max(0, min(A - 1, m + 1 - b) + 1)
            res = c1 * b
            cnt = A - c1
            if cnt > 0:
                res += cnt * (m + 1) - (c1 + A - 1) * cnt // 2
            return res

