class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def cnt(L, R):
            A = min(L - 1, k - 1)
            t = min(A, k - R)
            res = 0
            s = 0
            if t >= 0:
                res += (t + 1) * R
                s = t + 1
            if s <= A:
                hi = k - s
                lo = k - A
                res += (hi + lo) * (hi - lo + 1) // 2
            return res

        def solve(arr):
            # sum of min over subarrays with length <= k
            left = [0] * n
            right = [0] * n
            st = []
            for i in range(n):
                while st and arr[st[-1]] >= arr[i]:
                    st.pop()
                left[i] = i - (st[-1] if st else -1)
                st.append(i)
            st = []
            for i in range(n - 1, -1, -1):
                while st and arr[st[-1]] > arr[i]:
                    st.pop()
                right[i] = (st[-1] if st else n) - i
                st.append(i)
            total = 0
            for i in range(n):
                total += arr[i] * cnt(left[i], right[i])
            return total

        return solve(nums) - solve([-x for x in nums])
