class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def cnt(a, b):
            m = min(a - 1, k - 1)
            if m < 0:
                return 0
            t = k - b
            total = 0
            if t >= 0:
                total += (min(m, t) + 1) * b
            s = max(0, t + 1)
            if s <= m:
                c = m - s + 1
                total += c * k - (s + m) * c // 2
            return total

        def solve(arr):
            left = [-1] * n
            right = [n] * n
            st = []
            for i in range(n):
                while st and arr[st[-1]] >= arr[i]:
                    right[st.pop()] = i
                left[i] = st[-1] if st else -1
                st.append(i)
            res = 0
            for i in range(n):
                res += arr[i] * cnt(i - left[i], right[i] - i)
            return res

        return solve(nums) - solve([-x for x in nums])

