class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        W = m + 2
        H = n + 2
        G = [3] * (H * W)
        for i in range(n):
            row = grid[i]
            base = (i + 1) * W + 1
            for j in range(m):
                G[base + j] = row[j]
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        offs = [di * W + dj for di, dj in dirs]

        def order(d):
            di, dj = dirs[d]
            ri = range(n, 0, -1) if di == 1 else range(1, n + 1)
            rj = range(m, 0, -1) if dj == 1 else range(1, m + 1)
            res = []
            for i in ri:
                b = i * W
                for j in rj:
                    res.append(b + j)
            return res

        orders = [order(d) for d in range(4)]
        f = []
        for d in range(4):
            o = offs[d]
            fd = [0] * (H * W)
            for p in orders[d]:
                v = G[p]
                if v == 1:
                    continue
                q = p + o
                if G[q] == 2 - v:
                    fd[p] = 1 + fd[q]
                else:
                    fd[p] = 1
            f.append(fd)
        g = []
        for d in range(4):
            o = offs[d]
            d2 = (d + 1) % 4
            o2 = offs[d2]
            f2 = f[d2]
            gd = [0] * (H * W)
            for p in orders[d]:
                v = G[p]
                if v == 1:
                    continue
                t = 2 - v
                best = 1
                q = p + o
                if G[q] == t:
                    best = 1 + gd[q]
                q2 = p + o2
                if G[q2] == t:
                    c = 1 + f2[q2]
                    if c > best:
                        best = c
                gd[p] = best
            g.append(gd)
        ans = 0
        for p in range(H * W):
            if G[p] == 1:
                if ans < 1:
                    ans = 1
                for d in range(4):
                    q = p + offs[d]
                    if G[q] == 2:
                        c = 1 + g[d][q]
                        if c > ans:
                            ans = c
        return ans
