class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        W = m + 2
        H = n + 2
        g = [-1] * (W * H)
        for i in range(n):
            row = grid[i]
            base = (i + 1) * W + 1
            for j in range(m):
                g[base + j] = row[j]
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        size = W * H
        S = []
        orders = []
        for dr, dc in dirs:
            rows = range(n, 0, -1) if dr == 1 else range(1, n + 1)
            cols = range(m, 0, -1) if dc == 1 else range(1, m + 1)
            orders.append((rows, cols))
        for d in range(4):
            dr, dc = dirs[d]
            step = dr * W + dc
            s = [0] * size
            rows, cols = orders[d]
            for i in rows:
                base = i * W
                for j in cols:
                    idx = base + j
                    v = g[idx]
                    if v == 0 or v == 2:
                        nx = idx + step
                        if g[nx] == 2 - v:
                            s[idx] = s[nx] + 1
                        else:
                            s[idx] = 1
            S.append(s)
        T = []
        for d in range(4):
            dr, dc = dirs[d]
            step = dr * W + dc
            sp = S[(d + 1) % 4]
            t = [0] * size
            rows, cols = orders[d]
            for i in rows:
                base = i * W
                for j in cols:
                    idx = base + j
                    v = g[idx]
                    if v == 0 or v == 2:
                        a = sp[idx]
                        nx = idx + step
                        if g[nx] == 2 - v:
                            b = t[nx] + 1
                            if b > a:
                                a = b
                        t[idx] = a
            T.append(t)
        ans = 0
        steps = [dr * W + dc for dr, dc in dirs]
        for i in range(1, n + 1):
            base = i * W
            for j in range(1, m + 1):
                idx = base + j
                if g[idx] == 1:
                    if ans < 1:
                        ans = 1
                    for d in range(4):
                        nx = idx + steps[d]
                        if g[nx] == 2:
                            c = 1 + T[d][nx]
                            if c > ans:
                                ans = c
        return ans
