class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        E = []
        for di, dj in dirs:
            e = [[0] * m for _ in range(n)]
            rows = range(n - 1, -1, -1) if di == 1 else range(n)
            for i in rows:
                gi = grid[i]
                ei = e[i]
                ni = i + di
                inrow = 0 <= ni < n
                if inrow:
                    gn = grid[ni]
                    en = e[ni]
                for j in range(m):
                    v = gi[j]
                    if v == 1:
                        continue
                    val = 1
                    nj = j + dj
                    if inrow and 0 <= nj < m:
                        w = 0 if v == 2 else 2
                        if gn[nj] == w:
                            val += en[nj]
                    ei[j] = val
            E.append(e)

        ans = 0
        for k, (di, dj) in enumerate(dirs):
            d2i, d2j = dirs[(k + 1) % 4]
            E2 = E[(k + 1) % 4]
            H = [[0] * m for _ in range(n)]
            rows = range(n) if di == 1 else range(n - 1, -1, -1)
            for i in rows:
                gi = grid[i]
                hi = H[i]
                pi = i - di
                prow = 0 <= pi < n
                if prow:
                    gp = grid[pi]
                    hp = H[pi]
                ti = i + d2i
                trow = 0 <= ti < n
                if trow:
                    gt = grid[ti]
                    et = E2[ti]
                for j in range(m):
                    v = gi[j]
                    if v == 1:
                        h = 1
                    else:
                        h = 0
                        pj = j - dj
                        if prow and 0 <= pj < m and hp[pj]:
                            pv = gp[pj]
                            exp = 0 if pv == 2 else 2
                            if v == exp:
                                h = hp[pj] + 1
                    if h == 0:
                        continue
                    hi[j] = h
                    tot = h
                    tj = j + d2j
                    if trow and 0 <= tj < m:
                        w = 0 if v == 2 else 2
                        if gt[tj] == w:
                            tot += et[tj]
                    if tot > ans:
                        ans = tot
        return ans
