class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        W = m + 2
        N = (n + 2) * W
        g = [-1] * N
        for i in range(n):
            base = (i + 1) * W + 1
            row = grid[i]
            for j in range(m):
                g[base + j] = row[j]
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        offs = [di * W + dj for di, dj in dirs]
        A2s = []
        A0s = []
        for k in range(4):
            di = dirs[k][0]
            off = offs[k]
            A2 = [0] * N
            A0 = [0] * N
            rows = range(n, 0, -1) if di == 1 else range(1, n + 1)
            for r in rows:
                s = r * W + 1
                for p in range(s, s + m):
                    v = g[p]
                    if v == 2:
                        A2[p] = 1 + A0[p + off]
                    elif v == 0:
                        A0[p] = 1 + A2[p + off]
            A2s.append(A2)
            A0s.append(A0)
        best = 0
        for k in range(4):
            di = dirs[k][0]
            off = offs[k]
            k2 = (k + 1) % 4
            off2 = offs[k2]
            B2 = A2s[k2]
            B0 = A0s[k2]
            F = [0] * N
            rows = range(1, n + 1) if di == 1 else range(n, 0, -1)
            for r in rows:
                s = r * W + 1
                for p in range(s, s + m):
                    v = g[p]
                    f = 0
                    if v == 1:
                        f = 1
                    elif v == 2:
                        q = p - off
                        fq = F[q]
                        if fq and g[q] != 2:
                            f = fq + 1
                    elif v == 0:
                        q = p - off
                        fq = F[q]
                        if fq and g[q] == 2:
                            f = fq + 1
                    if f:
                        F[p] = f
                        if v == 2:
                            t = f + B0[p + off2]
                        else:
                            t = f + B2[p + off2]
                        if t > best:
                            best = t
        return best
