class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        events = defaultdict(int)
        total = 0
        for x, y, l in squares:
            total += l * l
            events[y] += l
            events[y + l] -= l
        keys = sorted(events)
        acc = 0  # area below current prev (exact integer)
        width = 0
        prev = keys[0]
        for k in keys:
            if width > 0:
                gain = width * (k - prev)
                if 2 * (acc + gain) >= total:
                    return prev + (total - 2 * acc) / (2 * width)
                acc += gain
            width += events[k]
            prev = k
        return float(prev)
