    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        # Z-function of str2
        z = [0] * m
        z[0] = m
        l = r = 0
        for i in range(1, m):
            if i < r:
                z[i] = min(r - i, z[i - l])
            while i + z[i] < m and str2[z[i]] == str2[i + z[i]]:
                z[i] += 1
            if i + z[i] > r:
                l, r = i, i + z[i]
        word = ['a'] * L
        fixed = [False] * L
        s2 = list(str2)
        prev = -1
        for i in range(n):
            if str1[i] == 'T':
                if prev != -1:
                    d = i - prev
                    if d < m and z[d] < m - d:
                        return ""
                word[i:i + m] = s2
                prev = i
        # mark fixed
        cover = 0  # furthest end covered
        for i in range(n):
            if str1[i] == 'T':
                start = max(i, cover)
                for j in range(start, i + m):
                    fixed[j] = True
                cover = max(cover, i + m)
        for i in range(n):
            if str1[i] == 'F':
                if word[i:i + m] == s2:
                    ok = False
                    for j in range(i + m - 1, i - 1, -1):
                        if not fixed[j]:
                            word[j] = 'b'
                            ok = True
                            break
                    if not ok:
                        return ""
        return ''.join(word)
