class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 2:
            return max(nums)
        # dp[i][j]: leftover nums[j], remaining from index i
        dp = [None] * (n + 2)
        for i in range(n, 0, -1):
            row = [0] * i
            if i == n:
                for j in range(i):
                    row[j] = nums[j]
            elif i == n - 1:
                b = nums[i]
                for j in range(i):
                    row[j] = max(nums[j], b)
            else:
                b = nums[i]
                c = nums[i + 1]
                nxt = dp[i + 2]
                opt1 = nxt[i + 1]
                opt2base = nxt[i]
                bc = max(b, c)
                for j in range(i):
                    a = nums[j]
                    v1 = (a if a > b else b) + opt1
                    v2 = (a if a > c else c) + opt2base
                    v3 = bc + nxt[j]
                    m = v1
                    if v2 < m:
                        m = v2
                    if v3 < m:
                        m = v3
                    row[j] = m
            dp[i] = row
        return dp[1][0]
