class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        OFF = 1800
        if abs(k) > OFF:
            return -1
        cap = limit + 1
        FULL = (1 << (2 * OFF + 1)) - 1
        dp = {}  # (parity, product) -> bitmask of sums
        for x in nums:
            new = dict(dp)
            for (p, prod), mask in dp.items():
                np_ = 1 - p
                nprod = prod * x
                if nprod > cap:
                    nprod = cap
                if p == 0:
                    nm = (mask << x) & FULL
                else:
                    nm = mask >> x
                if nm:
                    key = (np_, nprod)
                    new[key] = new.get(key, 0) | nm
            # start new subsequence with x
            key = (1, min(x, cap))
            new[key] = new.get(key, 0) | (1 << (OFF + x))
            dp = new
        best = -1
        bit = 1 << (OFF + k)
        for (p, prod), mask in dp.items():
            if prod <= limit and (mask & bit):
                if prod > best:
                    best = prod
        return best
