        total = sum(nums)
        if abs(k) > total:
            return -1
        cap = limit + 1
        states = set()  # (parity of next index, sum, product)
        for x in nums:
            new = set(states)
            new.add((1, x, x if x < cap else cap))
            for p, s, pr in states:
                np_ = pr * x
                if np_ > cap:
                    np_ = cap
                if p == 0:
                    new.add((1, s + x, np_))
                else:
                    new.add((0, s - x, np_))
            states = new
        best = -1
        for p, s, pr in states:
            if s == k and pr <= limit and pr > best:
                best = pr
        return best
