            # arrangements of remaining o odds, e evens, starting with parity nxt_odd
            if o == 0 and e == 0:
                return 1
            if nxt_odd:
                if not (o == e or o == e + 1):
                    return 0
            else:
                if not (e == o or e == o + 1):
                    return 0
            return min(fact[o] * fact[e], CAP)

        used = [False] * (n + 1)
        o = (n + 1) // 2
        e = n // 2
