            for x in range(1, n + 1):
                if used[x]:
                    continue
                if prev != -1 and (x % 2) == (prev % 2):
                    continue
                no, ne = o, e
                if x % 2 == 1:
                    no -= 1
                else:
                    ne -= 1
                # next parity is opposite of x
                cnt = ways(no, ne, x % 2 == 0)
                if k > cnt:
                    k -= cnt
                    continue
                used[x] = True
                res.append(x)
                prev = x
                o, e = no, ne
                placed = True
                break
            if not placed:
