class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [factorial(i) for i in range(n + 1)]
        used = [False] * (n + 1)
        odd_left = (n + 1) // 2
        even_left = n // 2
        res = []
        prev_par = -1
        for i in range(n):
            m = n - i - 1
            chosen = -1
            for x in range(1, n + 1):
                if used[x]:
                    continue
                par = x % 2
                if par == prev_par:
                    continue
                o = odd_left - (1 if par == 1 else 0)
                e = even_left - (1 if par == 0 else 0)
                # next parity is 1 - par
                need_next = (m + 1) // 2
                need_other = m // 2
                if 1 - par == 1:
                    ok = (o == need_next and e == need_other)
                else:
                    ok = (e == need_next and o == need_other)
                cnt = fact[o] * fact[e] if ok else 0
                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    break
            if chosen == -1:
                return []
            used[chosen] = True
            if chosen % 2 == 1:
                odd_left -= 1
            else:
                even_left -= 1
            prev_par = chosen % 2
            res.append(chosen)
        return res
