class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n
        children = [{}]
        cnt = [0]
        depth = [0]
        paths = []
        for w in words:
            node = 0
            p = [0]
            for ch in w:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(cnt)
                    children[node][ch] = nxt
                    children.append({})
                    cnt.append(0)
                    depth.append(depth[node] + 1)
                node = nxt
                cnt[node] += 1
                p.append(node)
            paths.append(p)
        maxlen = max(len(w) for w in words)
        good = [0] * (maxlen + 2)
        for v in range(1, len(cnt)):
            if cnt[v] >= k:
                good[depth[v]] += 1
        D = 0
        for d in range(1, maxlen + 1):
            if good[d] >= 1:
                D = d
        ans = []
        for i in range(n):
            p = paths[i]
            L = len(p) - 1
            d = D
            while d > 0:
                if good[d] >= 2:
                    break
                if d <= L and cnt[p[d]] == k:
                    d -= 1
                else:
                    break
            ans.append(d)
        return ans
