class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        ans = [0] * n
        if n - 1 < k:
            return ans
        order = sorted(range(n), key=words.__getitem__)
        s = [words[i] for i in order]
        if k == 1:
            L = [len(x) for x in s]
            pre = [0] * (n + 1)
            for i in range(n):
                pre[i + 1] = max(pre[i], L[i])
            suf = [0] * (n + 1)
            for i in range(n - 1, -1, -1):
                suf[i] = max(suf[i + 1], L[i])
            for p in range(n):
                ans[order[p]] = max(pre[p], suf[p + 1])
            return ans

        h = []
        for j in range(n - 1):
            a, b = s[j], s[j + 1]
            m = min(len(a), len(b))
            t = 0
            while t < m and a[t] == b[t]:
                t += 1
            h.append(t)

        def window_min(arr, size):
            res = []
            dq = deque()
            for i, v in enumerate(arr):
                while dq and arr[dq[-1]] >= v:
                    dq.pop()
                dq.append(i)
                if dq[0] <= i - size:
                    dq.popleft()
                if i >= size - 1:
                    res.append(arr[dq[0]])
            return res

        w = window_min(h, k - 1)   # length n-k+1
        w2 = window_min(h, k) if n - 1 >= k else []  # length n-k
        nw = len(w)
        pre = [0] * nw
        cur = 0
        for j in range(nw):
            cur = max(cur, w[j]); pre[j] = cur
        suf = [0] * (nw + 1)
        for j in range(nw - 1, -1, -1):
            suf[j] = max(suf[j + 1], w[j])

        # sparse table on w2
        m2 = len(w2)
        sp = [w2[:]]
        lg = 1
        while (1 << lg) <= m2:
            prev = sp[-1]
            half = 1 << (lg - 1)
            sp.append([max(prev[i], prev[i + half]) for i in range(m2 - (1 << lg) + 1)])
            lg += 1

        def qmax(l, r):
            if l > r:
                return 0
            b = (r - l + 1).bit_length() - 1
            t = sp[b]
            return max(t[l], t[r - (1 << b) + 1])

        for p in range(n):
            best = 0
            if p - k >= 0:
                best = pre[p - k]
            if p + 1 <= nw - 1:
                best = max(best, suf[p + 1])
            l = max(0, p - k + 1)
            r = min(p - 1, m2 - 1)
            if l <= r:
                best = max(best, qmax(l, r))
            ans[order[p]] = best
        return ans
