            return [0] * n
        order = sorted(range(n), key=lambda i: words[i])
        s = [words[i] for i in order]
        h = []
        for j in range(n - 1):
            a, b = s[j], s[j + 1]
            m = min(len(a), len(b))
            t = 0
            while t < m and a[t] == b[t]:
                t += 1
            h.append(t)

        def build(arr, f):
            tab = [arr[:]]
            L = len(arr)
            step = 1
            while 2 * step <= L:
                prev = tab[-1]
                tab.append([f(prev[i], prev[i + step]) for i in range(L - 2 * step + 1)])
                step *= 2
            return tab

        def query(tab, l, r, f):
            ln = r - l + 1
            lg = ln.bit_length() - 1
            return f(tab[lg][l], tab[lg][r - (1 << lg) + 1])

        hmin = build(h, min) if h else None
        # w[j] for j in 0..n-k
        if k == 1:
            w = [len(x) for x in s]
        else:
            w = [query(hmin, j, j + k - 2, min) for j in range(n - k + 1)]
        # v[j] for j in 0..n-k-1 : min(h[j..j+k-1])
        v = [query(hmin, j, j + k - 1, min) for j in range(n - k)]
        vmax = build(v, max) if v else None

        W = len(w)
        pm = [0] * W
        cur = 0
        for j in range(W):
            cur = max(cur, w[j])
            pm[j] = cur
        sm = [0] * (W + 1)
        for j in range(W - 1, -1, -1):
            sm[j] = max(sm[j + 1], w[j])

        res = [0] * n
        for p in range(n):
            best = 0
            if p - k >= 0:
                best = pm[min(p - k, W - 1)]
            if p + 1 < W:
                best = max(best, sm[p + 1])
            lo = max(0, p - k + 1)
            hi = min(p - 1, n - 1 - k)
            if lo <= hi and v:
                best = max(best, query(vmax, lo, hi, max))
            res[order[p]] = best
        return res

