class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        byb = [[] for _ in range(n + 1)]
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            byb[b].append(a)
        m1 = 0
        m2 = 0
        base = 0
        gain = [0] * (n + 1)
        for r in range(1, n + 1):
            for a in byb[r]:
                if a > m1:
                    m2 = m1
                    m1 = a
                elif a > m2:
                    m2 = a
            base += r - m1
            gain[m1] += m1 - m2
        return base + max(gain[1:]) if n >= 1 else base
