class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        size = 1
        while size < n:
            size *= 2
        tree = [0] * (2 * size)
        for i, b in enumerate(baskets):
            tree[size + i] = b
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])
        unplaced = 0
        for f in fruits:
            if tree[1] < f:
                unplaced += 1
                continue
            i = 1
            while i < size:
                if tree[2 * i] >= f:
                    i = 2 * i
                else:
                    i = 2 * i + 1
            tree[i] = 0
            i //= 2
            while i:
                tree[i] = max(tree[2 * i], tree[2 * i + 1])
                i //= 2
        return unplaced
