class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(n):
            if n <= 0:
                return 0
            digs = list(map(int, str(n)))
            L = len(digs)
            suffix_val = [0] * (L + 1)
            for i in range(L - 1, -1, -1):
                suffix_val[i] = int(str(n)[i:]) if i < L else 0

            @lru_cache(maxsize=None)
            def dfs(pos, s, p, tight, started):
                if pos == L:
                    return 1 if (started and p % s == 0) else 0
                if started and p == 0:
                    rem = L - pos
                    if not tight:
                        return 10 ** rem
                    else:
                        return suffix_val[pos] + 1
                lim = digs[pos] if tight else 9
                total = 0
                for d in range(lim + 1):
                    nt = tight and d == lim
                    if not started:
                        if d == 0:
                            total += dfs(pos + 1, 0, 1, nt, False)
                        else:
                            total += dfs(pos + 1, d, d, nt, True)
                    else:
                        total += dfs(pos + 1, s + d, p * d, nt, True)
                return total

            res = dfs(0, 0, 1, True, False)
            dfs.cache_clear()
            return res

        return count(r) - count(l - 1)
