class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        @lru_cache(maxsize=None)
        def dfs(rem, s, p):
            if rem == 0:
                return 1 if p % s == 0 else 0
            total = 10 ** (rem - 1)
            for d in range(1, 10):
                total += dfs(rem - 1, s + d, p * d)
            return total

        def f(n):
            if n <= 0:
                return 0
            ds = list(map(int, str(n)))
            m = len(ds)
            res = 0
            for L in range(1, m):
                for d in range(1, 10):
                    res += dfs(L - 1, d, d)
            s, p = 0, 1
            for i, nd in enumerate(ds):
                rem = m - i - 1
                start = 1 if i == 0 else 0
                for d in range(start, nd):
                    if d == 0 or p == 0:
                        res += 10 ** rem
                    else:
                        res += dfs(rem, s + d, p * d)
                s += nd
                p *= nd
            if p % s == 0:
                res += 1
            return res

        return f(r) - f(l - 1)
