class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ones = s.count('1')
        zeros = []
        n = len(s)
        i = 0
        while i < n:
            if s[i] == '0':
                j = i
                while j < n and s[j] == '0':
                    j += 1
                zeros.append(j - i)
                i = j
            else:
                i += 1
        best = 0
        for k in range(len(zeros) - 1):
            best = max(best, zeros[k] + zeros[k + 1])
        return ones + best
