from itertools import permutations
import bisect

def main():
    M = int(input())
    S = [input().strip() for _ in range(3)]
    INF = float('inf')
    best = INF
    for d in "0123456789":
        lists = []
        for i in range(3):
            lists.append([t for t in range(3 * M) if S[i][t % M] == d])
        if any(len(l) == 0 for l in lists):
            continue
        for perm in permutations(range(3)):
            prev = -1
            ok = True
            for i in perm:
                l = lists[i]
                k = bisect.bisect_right(l, prev)
                if k >= len(l):
                    ok = False
                    break
                prev = l[k]
            if ok:
                best = min(best, prev)
    print(best if best < INF else -1)

