        for _ in range(4):
            cur = [(col, 3 - r) for r, col in cur]
            mr = min(r for r, _ in cur)
            mc = min(col for _, col in cur)
            norm = [(r - mr, col - mc) for r, col in cur]
            hr = max(r for r, _ in norm)
            hc = max(col for _, col in norm)
            for dr in range(4 - hr):
                for dc in range(4 - hc):
                    m = 0
                    for r, col in norm:
