    data=sys.stdin.buffer.read().split()
    n=int(data[0]); t=data[1].decode()
    L=len(t)
    res=[]
    for i in range(n):
        s=data[2+i].decode()
        M=len(s)
        if M<L-1 or M>L+1:
            continue
        if s==t:
            res.append(i+1); continue
        m=min(M,L)
        p=0
        while p<m and s[p]==t[p]:
            p+=1
        q=0
        while q<m and s[M-1-q]==t[L-1-q]:
            q+=1
        if M==L:
            ok = p+q>=L-1
        elif M==L+1:
            ok = p+q>=L
        else:
            ok = p+q>=M
        if ok:
            res.append(i+1)
    sys.stdout.write(str(len(res))+"\n"+" ".join(map(str,res))+"\n")
main()

