from itertools import permutations

def main():
    data = sys.stdin.read().split()
    n = int(data[0]); R = data[1]; C = data[2]
    letters = "ABC"
    rowopts = []
    for i in range(n):
        opts = []
        for p in permutations(range(n), 3):
            # p[k] = column of letters[k]
            m = min(p)
            k = p.index(m)
            if letters[k] == R[i]:
                opts.append(p)
        rowopts.append(opts)
    colmask = [0]*n
    started = [False]*n
    grid = [['.']*n for _ in range(n)]
    sys.setrecursionlimit(10000)

    def dfs(i):
        if i == n:
            return all(m == 7 for m in colmask)
        rem = n - i
        for j in range(n):
            if 3 - bin(colmask[j]).count('1') > rem:
                return False
        for p in rowopts[i]:
            ok = True
            for k in range(3):
                j = p[k]
                if colmask[j] >> k & 1:
                    ok = False; break
                if not started[j] and letters[k] != C[j]:
                    ok = False; break
            if not ok:
                continue
            saved = [(j, colmask[j], started[j]) for j in p]
            for k in range(3):
                j = p[k]
                colmask[j] |= 1 << k
                started[j] = True
                grid[i][j] = letters[k]
            if dfs(i+1):
                return True
            for j, m, s in saved:
                colmask[j] = m
                started[j] = s
                grid[i][j] = '.'
        return False

    if dfs(0):
        print("Yes")
        print("\n".join("".join(r) for r in grid))
    else:
        print("No")

main()
