import sys
from itertools import permutations
def main():
    d=sys.stdin.read().split()
    n=int(d[0]); R=d[1]; C=d[2]
    cand={}
    for ch in "ABC":
        lst=[]
        for p in permutations(range(n),3):
            # p[0]=col of A, p[1]=col of B, p[2]=col of C
            m=min(p)
            if "ABC"[p.index(m)]!=ch: continue
            lst.append(p)
        cand[ch]=lst
    used=[0]*n  # bitmask of letters used
    grid=[None]*n
    sys.setrecursionlimit(10000)
    def rec(i):
        rem=n-i
        for j in range(n):
            if 3-bin(used[j]).count('1')>rem: return False
        if i==n:
            return True
        for p in cand[R[i]]:
            ok=True
            for k in range(3):
                j=p[k]
                if used[j]>>k&1: ok=False;break
                if used[j]==0 and C[j]!="ABC"[k]: ok=False;break
            if not ok: continue
            for k in range(3): used[p[k]]|=1<<k
            grid[i]=p
            if rec(i+1): return True
            for k in range(3): used[p[k]]^=1<<k
        return False
    if rec(0):
        out=["Yes"]
        for p in grid:
            row=['.']*n
            for k in range(3): row[p[k]]="ABC"[k]
            out.append("".join(row))
        print("\n".join(out))
    else:
        print("No")
main()

