def main():
    data = sys.stdin.read().split()
    vals = list(map(int, data[:81]))
    A = [vals[i*9:(i+1)*9] for i in range(9)]
    target = set(range(1, 10))
    ok = True
    for i in range(9):
        if set(A[i]) != target:
            ok = False
        if set(A[r][i] for r in range(9)) != target:
            ok = False
