import sys
def main():
    data=sys.stdin.read().split()
    n,m=int(data[0]),int(data[1])
    s=list(data[2]); t=data[3]
    def ok(i):
        # returns True if window can be undone and has some non-#
        has=False
        for j in range(m):
            c=s[i+j]
            if c=='#': continue
            if c!=t[j]: return False
            has=True
        return has
    stack=[i for i in range(n-m+1) if ok(i)]
    while stack:
        i=stack.pop()
        if not ok(i): continue
        for j in range(m):
            s[i+j]='#'
        lo=max(0,i-m+1); hi=min(n-m,i+m-1)
        for k in range(lo,hi+1):
            if ok(k):
                stack.append(k)
    print("Yes" if all(c=='#' for c in s) else "No")
