import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    s = list(data[2])
    t = data[3]

    def ok(i):
        # Window [i, i+m) can be undone: every char is '#' or matches T,
        # and at least one char is not '#'.
        has = False
        for j in range(m):
            c = s[i + j]
            if c == '#':
                continue
            if c != t[j]:
                return False
            has = True
        return has

    q = deque()
    for i in range(n - m + 1):
        if ok(i):
            q.append(i)

    while q:
        i = q.popleft()
        if not ok(i):
            continue
        for j in range(m):
            s[i + j] = '#'
        for k in range(max(0, i - m + 1), min(n - m, i + m - 1) + 1):
            if ok(k):
                q.append(k)

    print("Yes" if all(c == '#' for c in s) else "No")

main()
import sys
from collections import deque
def main():
    data=sys.stdin.read().split()
    n=int(data[0]); m=int(data[1])
    s=list(data[2]); t=data[3]
    def ok(i):
        if i<0 or i+m>n: return False
        for k in range(m):
            c=s[i+k]
            if c!='#' and c!=t[k]: return False
        return True
    done=[False]*(n)
    q=deque()
    for i in range(n-m+1):
        if ok(i):
            done[i]=True
            q.append(i)
    while q:
        i=q.popleft()
        for k in range(m):
            p=i+k
            if s[p]!='#':
                s[p]='#'
                for j in range(max(0,p-m+1),min(p,n-m)+1):
                    if not done[j] and ok(j):
                        done[j]=True
                        q.append(j)
    print("Yes" if all(c=='#' for c in s) else "No")
main()

