    for i in range(n):
        a, b = int(data[3+2*i]), int(data[4+2*i])
        tiles.append((a, b))
    grid = [[False]*W for _ in range(H)]

    def dfs(used, subset):
        # find first empty cell
        pos = -1
        for idx in range(H*W):
            r, c = divmod(idx, W)
            if not grid[r][c]:
                pos = idx
                break
        if pos == -1:
            return True
        r, c = divmod(pos, W)
        for i in subset:
            if used[i]:
                continue
            a, b = tiles[i]
            orients = [(a, b)] if a == b else [(a, b), (b, a)]
            for h, w in orients:
                if r + h > H or c + w > W:
                    continue
                ok = True
                for y in range(r, r+h):
                    row = grid[y]
                    for x in range(c, c+w):
                        if row[x]:
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    continue
                for y in range(r, r+h):
                    for x in range(c, c+w):
                        grid[y][x] = True
                used[i] = True
                if dfs(used, subset):
                    return True
                used[i] = False
                for y in range(r, r+h):
                    for x in range(c, c+w):
                        grid[y][x] = False
        return False

    for mask in range(1, 1 << n):
        subset = [i for i in range(n) if mask >> i & 1]
        if sum(tiles[i][0]*tiles[i][1] for i in subset) != H*W:
            continue
        for y in range(H):
            for x in range(W):
                grid[y][x] = False
        if dfs([False]*n, subset):
            print("Yes")
