import sys, heapq
def main():
    data=sys.stdin.read().split()
    H=int(data[0]);W=int(data[1])
    g=data[2:2+H]
    idx=2+H
    n=int(data[idx]);idx+=1
    med=[0]*(H*W)
    for _ in range(n):
        r=int(data[idx])-1;c=int(data[idx+1])-1;e=int(data[idx+2]);idx+=3
        med[r*W+c]=e
    blocked=[False]*(H*W)
    s=t=0
    for i in range(H):
        row=g[i]
        for j in range(W):
            ch=row[j]
            if ch=='#':blocked[i*W+j]=True
            elif ch=='S':s=i*W+j
            elif ch=='T':t=i*W+j
    best=[-1]*(H*W)
    best[s]=0
    pq=[(0,s)]
    while pq:
        ne,v=heapq.heappop(pq)
        e=-ne
        if e<best[v]:continue
        if v==t:
            print("Yes");return
        e2=max(e,med[v])
        best[v]=e2
        if e2<=0:continue
        ne2=e2-1
        i,j=divmod(v,W)
        if i>0:
            u=v-W
            if not blocked[u] and best[u]<ne2:
                best[u]=ne2;heapq.heappush(pq,(-ne2,u))
        if i<H-1:
            u=v+W
            if not blocked[u] and best[u]<ne2:
                best[u]=ne2;heapq.heappush(pq,(-ne2,u))
        if j>0:
            u=v-1
            if not blocked[u] and best[u]<ne2:
                best[u]=ne2;heapq.heappush(pq,(-ne2,u))
        if j<W-1:
            u=v+1
            if not blocked[u] and best[u]<ne2:
                best[u]=ne2;heapq.heappush(pq,(-ne2,u))
    print("No")
