def main():
    data=sys.stdin.buffer.read().split()
    H=int(data[0]);W=int(data[1])
    rows=[data[2+i].decode() for i in range(H)]
    n=int(data[2+H])
    grid=bytearray(H*W)
    s=t=-1
    for i in range(H):
        r=rows[i]
        for j in range(W):
            c=r[j]
            if c!='#':
                grid[i*W+j]=1
            if c=='S': s=i*W+j
            elif c=='T': t=i*W+j
    med={}
    pos=[];en=[]
    idx=3+H
    for k in range(n):
        r=int(data[idx])-1;c=int(data[idx+1])-1;e=int(data[idx+2]);idx+=3
        p=r*W+c
        med[p]=k
        pos.append(p);en.append(e)
    if s not in med:
        print("No");return
    HW=H*W
    def bfs(src,E):
        # returns list of medicine indices reachable, and whether t reachable
        dist={src:0}
        dq=deque([src])
        res=[];reachT=False
        while dq:
            v=dq.popleft()
            d=dist[v]
            if v==t: reachT=True
            if v in med: res.append(med[v])
            if d==E: continue
            r,c=divmod(v,W)
            nd=d+1
            if c>0:
                u=v-1
                if grid[u] and u not in dist:
                    dist[u]=nd;dq.append(u)
            if c<W-1:
                u=v+1
                if grid[u] and u not in dist:
                    dist[u]=nd;dq.append(u)
            if r>0:
                u=v-W
                if grid[u] and u not in dist:
                    dist[u]=nd;dq.append(u)
            if r<H-1:
                u=v+W
                if grid[u] and u not in dist:
                    dist[u]=nd;dq.append(u)
        return res,reachT
    start=med[s]
    seen=[False]*n
    seen[start]=True
    q=deque([start])
    while q:
        k=q.popleft()
        res,rt=bfs(pos[k],en[k])
        if rt:
            print("Yes");return
        for m in res:
            if not seen[m]:
                seen[m]=True;q.append(m)
    print("No")
