                if ch=='S': s=i*W+j
                elif ch=='T': t=i*W+j
    med={}
    pos=[];E=[]
    for k in range(N):
        r=int(data[p])-1;c=int(data[p+1])-1;e=int(data[p+2]);p+=3
        pos.append(r*W+c);E.append(e);med[r*W+c]=k
    if s not in med:
        print("No");return
    HW=H*W
    def bfs(src,lim):
        dist=[-1]*HW
        dist[src]=0
        dq=deque([src])
        res=[]
        while dq:
            v=dq.popleft()
            d=dist[v]
            if v in med: res.append(med[v])
            if v==t: res.append(-1)
            if d==lim: continue
            r,c=divmod(v,W)
            nd=d+1
            if r>0:
                u=v-W
                if free[u] and dist[u]<0: dist[u]=nd; dq.append(u)
            if r<H-1:
                u=v+W
                if free[u] and dist[u]<0: dist[u]=nd; dq.append(u)
            if c>0:
                u=v-1
                if free[u] and dist[u]<0: dist[u]=nd; dq.append(u)
            if c<W-1:
                u=v+1
                if free[u] and dist[u]<0: dist[u]=nd; dq.append(u)
        return res
    seen=[False]*N
    st=med[s]
    seen[st]=True
    stack=[st]
    while stack:
        k=stack.pop()
        for x in bfs(pos[k],E[k]):
            if x==-1:
                print("Yes");return
            if not seen[x]:
                seen[x]=True
                stack.append(x)
    print("No")
