import sys
def main():
    data=sys.stdin.buffer.read().split()
    H=int(data[0]);W=int(data[1])
    W2=W+2
    N=(H+2)*W2
    mag=bytearray(b'\x01')*N
    for i in range(H):
        row=data[2+i]
        base=(i+1)*W2+1
        mag[base:base+W]=row.translate(bytes.maketrans(b'.#',b'\x00\x01'))
    # free: empty and no neighbor magnet (border padding counts as magnet but border isn't outside grid... careful)
    # border cells are out of grid, not magnets; neighbor out-of-grid shouldn't block.
    # so build separate isMagnet array where border = 0, and wall array where border=1
    ism=bytearray(N)
    for i in range(H):
        base=(i+1)*W2+1
        ism[base:base+W]=mag[base:base+W]
    free=bytearray(N)
    for p in range(W2,N-W2):
        if not mag[p] and not ism[p-1] and not ism[p+1] and not ism[p-W2] and not ism[p+W2]:
            free[p]=1
    # mag (with border as wall) means not enterable
    seen=bytearray(N)
    mark=[0]*N
    best=1
    cid=0
    for s in range(W2,N-W2):
        if free[s] and not seen[s]:
            cid+=1
            seen[s]=1
            q=[s]
            cnt=0
            for p in q:
                cnt+=1
                for nb in (p-1,p+1,p-W2,p+W2):
                    if mag[nb]:
                        continue
                    if free[nb]:
                        if not seen[nb]:
                            seen[nb]=1
                            q.append(nb)
                    else:
                        if mark[nb]!=cid:
                            mark[nb]=cid
                            cnt+=1
            if cnt>best: best=cnt
    print(best)
main()
