    data=sys.stdin.buffer.read().split()
    H=int(data[0]); W=int(data[1])
    W2=W+2
    N=(H+2)*W2
    mag=bytearray(b'\x01')*N
    for i in range(H):
        row=data[2+i]
        base=(i+1)*W2+1
        mag[base:base+W]=row.translate(bytes.maketrans(b'.#',b'\x00\x01'))
    # free: empty and no magnet neighbor (padding counts as magnet, but grid exit isn't a magnet!)
    # padding must not count as magnet for freeness; use separate realmag
    realmag=bytearray(N)
    for i in range(H):
        row=data[2+i]
        base=(i+1)*W2+1
        realmag[base:base+W]=row.translate(bytes.maketrans(b'.#',b'\x00\x01'))
    free=bytearray(N)
    for i in range(1,H+1):
        for p in range(i*W2+1,i*W2+W+1):
            if not mag[p] and not realmag[p-1] and not realmag[p+1] and not realmag[p-W2] and not realmag[p+W2]:
                free[p]=1
    seen=bytearray(N)
    mark=[0]*N
    best=1
    cid=0
    for s in range(N):
        if free[s] and not seen[s]:
            cid+=1
            seen[s]=1
            stack=[s]
            cnt=0
            while stack:
                p=stack.pop()
                cnt+=1
                for q in (p-1,p+1,p-W2,p+W2):
                    if mag[q]:
                        continue
                    if free[q]:
                        if not seen[q]:
                            seen[q]=1
                            stack.append(q)
                    else:
                        if mark[q]!=cid:
                            mark[q]=cid
                            cnt+=1
            if cnt>best:
                best=cnt
    print(best)
main()
