import sys
def main():
    data=sys.stdin.buffer.read().split()
    H=int(data[0]); W=int(data[1])
    N=H*W
    mag=bytearray(N)
    for i in range(H):
        row=data[2+i]
        base=i*W
        for j in range(W):
            if row[j]==35:
                mag[base+j]=1
    # free cells
    free=bytearray(N)
    for i in range(H):
        base=i*W
        for j in range(W):
            p=base+j
            if mag[p]: continue
            ok=True
            if i>0 and mag[p-W]: ok=False
            elif i<H-1 and mag[p+W]: ok=False
            elif j>0 and mag[p-1]: ok=False
            elif j<W-1 and mag[p+1]: ok=False
            if ok: free[p]=1
    visited=bytearray(N)
    mark=[-1]*N
    best=1
    cid=0
    for s in range(N):
        if not free[s] or visited[s]: continue
        cid+=1
        visited[s]=1
        stack=[s]
        cnt=0
        while stack:
            p=stack.pop()
            cnt+=1
            i,j=divmod(p,W)
            nb=[]
            if i>0: nb.append(p-W)
            if i<H-1: nb.append(p+W)
            if j>0: nb.append(p-1)
            if j<W-1: nb.append(p+1)
            for q in nb:
                if free[q]:
                    if not visited[q]:
                        visited[q]=1
                        stack.append(q)
                else:
                    # q is not magnet (since p is free), so it's stuck empty
                    if mark[q]!=cid:
                        mark[q]=cid
                        cnt+=1
        if cnt>best: best=cnt
    print(best)
