import sys
from collections import deque
def main():
    d=sys.stdin.buffer.read().split()
    n=int(d[0]);k=int(d[1])
    pos=[0]*n
    for i in range(n):
        pos[int(d[2+i])-1]=i
    mx=deque();mn=deque()
    best=n
    for i in range(n):
        p=pos[i]
        while mx and pos[mx[-1]]<=p: mx.pop()
        mx.append(i)
        while mn and pos[mn[-1]]>=p: mn.pop()
        mn.append(i)
        if mx[0]<=i-k: mx.popleft()
        if mn[0]<=i-k: mn.popleft()
        if i>=k-1:
            v=pos[mx[0]]-pos[mn[0]]
            if v<best: best=v
    print(best)
