import sys
def main():
    data=sys.stdin.read().split()
    n=int(data[0]); m=int(data[1])
    adj=[0]*n
    for i in range(m):
        u=int(data[2+2*i])-1; v=int(data[3+2*i])-1
        adj[u]|=1<<v; adj[v]|=1<<u
    rows=[adj[i] for i in range(n) if adj[i]]
    # RREF
    pivots=[]  # (col,row)
    r=0
    for c in range(n):
        sel=-1
        for i in range(r,len(rows)):
            if rows[i]>>c&1:
                sel=i;break
        if sel<0: continue
        rows[r],rows[sel]=rows[sel],rows[r]
        for i in range(len(rows)):
            if i!=r and rows[i]>>c&1:
                rows[i]^=rows[r]
        pivots.append((c,r))
        r+=1
    pivcols=set(c for c,_ in pivots)
    basis=[]
    for f in range(n):
        if f in pivcols: continue
        x=1<<f
        for c,ri in pivots:
            if rows[ri]>>f&1:
                x|=1<<c
        basis.append(x)
    cov=0
    for b in basis: cov|=b
    if cov!=(1<<n)-1:
        print("No"); return
    X=[0]*n
    for i,b in enumerate(basis):
        for v in range(n):
            if b>>v&1:
                X[v]|=1<<i
    print("Yes")
    print(*X)
main()
