def main():
    data=sys.stdin.buffer.read().split()
    H=int(data[0]);W=int(data[1]);Q=int(data[2])
    rl=[0]*(H*W); rr=[0]*(H*W); cu=[0]*(H*W); cd=[0]*(H*W)
    for r in range(H):
        b=r*W
        for c in range(W):
            rl[b+c]=c; rr[b+c]=c
    for c in range(W):
        b=c*H
        for r in range(H):
            cu[b+r]=r; cd[b+r]=r
    alive=[True]*(H*W)
    destroyed=0
    def find(arr,base,x,lim):
        root=x
        while 0<=root<lim and arr[base+root]!=root:
            root=arr[base+root]
        while x!=root:
            nx=arr[base+x]; arr[base+x]=root; x=nx
        return root
    def kill(r,c):
        rl[r*W+c]=c-1; rr[r*W+c]=c+1
        cu[c*H+r]=r-1; cd[c*H+r]=r+1
        alive[r*W+c]=False
    idx=3
    for _ in range(Q):
        r=int(data[idx])-1;c=int(data[idx+1])-1;idx+=2
        if alive[r*W+c]:
            kill(r,c);destroyed+=1;continue
        t=[]
        if c-1>=0:
            x=find(rl,r*W,c-1,W)
            if x>=0: t.append((r,x))
