    n=int(data[0])
    P=[int(x)-1 for x in data[1:1+n]]
    A=[int(x) for x in data[1+n:1+2*n]]
    spf=list(range(n+1))
    i=2
    while i*i<=n:
        if spf[i]==i:
            for j in range(i*i,n+1,i):
                if spf[j]==j: spf[j]=i
        i+=1
    E={}  # prime -> (pe value p^e, residue)
    seen=[False]*n
    res=[0]*n
    for st in range(n):
        if seen[st]: continue
        cyc=[]
        x=st
        while not seen[x]:
            seen[x]=True
            cyc.append(x)
            x=P[x]
        L=len(cyc)
        # factor
        fac=[]
        m=L
        while m>1:
            p=spf[m]; q=1
            while m%p==0:
                m//=p; q*=p
            fac.append((p,q))
        checks=[]
        for p,q in fac:
            if p in E:
                pe,r=E[p]
                g=min(pe,q)
                checks.append((g,r%g))
        best=-1;bv=n+5
