import sys
def main():
    sys.setrecursionlimit(10000)
    data = sys.stdin.read().split()
    n = int(data[0])
    S = data[1:1+n]
    by_first = {}
    for i, s in enumerate(S):
        by_first.setdefault(s[0], []).append(i)
    adj = [by_first.get(s[1], []) for s in S]

    # Tarjan
    index = [-1]*n
    low = [0]*n
    onst = [False]*n
    st = []
    comp = [-1]*n
    cnt = [0]
    ncomp = [0]
    def dfs(u):
        index[u] = low[u] = cnt[0]; cnt[0] += 1
        st.append(u); onst[u] = True
        for v in adj[u]:
            if index[v] == -1:
                dfs(v)
                if low[v] < low[u]: low[u] = low[v]
            elif onst[v]:
                if index[v] < low[u]: low[u] = index[v]
        if low[u] == index[u]:
            c = ncomp[0]; ncomp[0] += 1
            while True:
                w = st.pop(); onst[w] = False; comp[w] = c
                if w == u: break
    for i in range(n):
        if index[i] == -1:
            dfs(i)
    C = ncomp[0]
    members = [[] for _ in range(C)]
    for i in range(n):
        members[comp[i]].append(i)
    reach = [0]*C
    for c in range(C):  # sinks first
        r = 0
        for u in members[c]:
            for v in adj[u]:
                d = comp[v]
                if d != c:
                    r |= (1 << d) | reach[d]
        reach[c] = r

    matchR = [-1]*C
    def tr(u, vis):
