    # Kosaraju
    visited = [False]*n
    order = []
    for s in range(n):
        if visited[s]:
            continue
        visited[s] = True
        stack = [(s, 0)]
        while stack:
            u, idx = stack[-1]
            if idx < len(adj[u]):
                stack[-1] = (u, idx+1)
                v = adj[u][idx]
                if not visited[v]:
                    visited[v] = True
                    stack.append((v, 0))
            else:
                stack.pop()
                order.append(u)
    comp = [-1]*n
    c = 0
    for s in reversed(order):
        if comp[s] != -1:
            continue
        comp[s] = c
        st = [s]
        while st:
            u = st.pop()
            for v in radj[u]:
                if comp[v] == -1:
                    comp[v] = c
                    st.append(v)
        c += 1
    C = c
    succ = [set() for _ in range(C)]
    for i in range(n):
        ci = comp[i]
        for j in adj[i]:
            cj = comp[j]
            if cj != ci:
                succ[ci].add(cj)
    reach = [0]*C
    for x in range(C-1, -1, -1):
        r = 0
        for d in succ[x]:
            r |= (1 << d) | reach[d]
        reach[x] = r
    match = [-1]*C
    vis = [0]
    def tr(u):
        cand = reach[u] & vis[0]
        while cand:
            low = cand & -cand
            v = low.bit_length()-1
            if vis[0] & low:
                vis[0] &= ~low
                if match[v] == -1 or tr(match[v]):
                    match[v] = u
                    return True
            cand &= ~low
            cand &= vis[0]
        return False
    full = (1 << C) - 1
    m = 0
    for u in range(C):
        vis[0] = full
        if tr(u):
            m += 1
    print(C - m)
