def main():
    data = sys.stdin.read().split()
    H, W = int(data[0]), int(data[1])
    g = data[2:2+H]
    if W > H:
        g = [''.join(g[i][j] for i in range(H)) for j in range(W)]
        H, W = W, H
    MOD = 998244353
    mask = (1 << (2*W)) - 1
    sh = 2*(W-1)
    # valid rows
    rows = []
    def gen(k, prev, val):
        if k == W:
            rows.append(val); return
        for c in (1, 2, 3):
            if c != prev:
                gen(k+1, c, (val << 2) | c)
    gen(0, 0, 0)
    S = [None]*(W+1)
    S[0] = sorted(rows)
    trans = [None]*W  # trans[j][u][c] = (src, tgt)
    for j in range(W):
        cur = S[j]
        lst = []
        tset = set()
        for idx, s in enumerate(cur):
            up = (s >> sh) & 3
            left = (s & 3) if j > 0 else 0
            for c in (1, 2, 3):
                if c != up and c != left:
                    ns = ((s << 2) & mask) | c
                    lst.append((idx, ns, up, c))
                    tset.add(ns)
        if j + 1 < W:
            S[j+1] = sorted(tset)
            nxt = S[j+1]
        else:
            nxt = S[0]
        ind = {s: i for i, s in enumerate(nxt)}
        groups = [[[[], []] for _ in range(4)] for _ in range(4)]
        for idx, ns, up, c in lst:
            gr = groups[up][c]
            gr[0].append(idx); gr[1].append(ind[ns])
        tr = [[None]*4 for _ in range(4)]
        for u in range(4):
            for c in range(4):
                if groups[u][c][0]:
                    tr[u][c] = (np.array(groups[u][c][0], dtype=np.int64),
                                np.array(groups[u][c][1], dtype=np.int64))
        trans[j] = tr
    # initial
    old = np.zeros(len(S[0]), dtype=np.int64)
    r0 = g[0]
    for idx, s in enumerate(S[0]):
        ok = True
        for k in range(W):
            v = (s >> (2*(W-1-k))) & 3
            ch = r0[k]
            if ch != '?' and int(ch) != v:
                ok = False; break
        if ok:
            old[idx] = 1
    for i in range(1, H):
        row = g[i]
        for j in range(W):
            ch = row[j]
            allowed = (1, 2, 3) if ch == '?' else (int(ch),)
            nlen = len(S[(j+1) % W])
            new = np.zeros(nlen, dtype=np.int64)
            tr = trans[j]
            for u in range(4):
                for c in allowed:
                    t = tr[u][c]
                    if t is not None:
                        new[t[1]] += old[t[0]]
            new %= MOD
            old = new
    print(int(old.sum() % MOD))

