    S = data[2:2+H]
    MOD = 998244353
    if W > H:
        S = [''.join(S[i][j] for i in range(H)) for j in range(W)]
        H, W = W, H
    N = 3 ** W
    dp = np.zeros(N, dtype=np.int64)
    dp[0] = 1
    for i in range(H):
        for j in range(W):
            ch = S[i][j]
            if ch == '?':
                allowed = [True, True, True]
            else:
                allowed = [False, False, False]
                allowed[int(ch) - 1] = True
            R = 3 ** (W - 1 - j)
            if j == 0:
                v = dp.reshape(3, R)
                tot = v.sum(axis=0)
                new = np.zeros((3, R), dtype=np.int64)
                for c in range(3):
                    if allowed[c]:
                        if i == 0:
                            new[c] = tot
                        else:
                            new[c] = tot - v[c]
                new %= MOD
                dp = new.reshape(N)
            else:
                L = 3 ** (j - 1)
                v = dp.reshape(L, 3, 3, R)
                tot = v.sum(axis=2)  # (L,3,R)
                new = np.zeros((L, 3, 3, R), dtype=np.int64)
                for l in range(3):
                    for c in range(3):
                        if c != l and allowed[c]:
                            if i == 0:
                                new[:, l, c, :] = tot[:, l, :]
                            else:
                                new[:, l, c, :] = tot[:, l, :] - v[:, l, c, :]
                new %= MOD
                dp = new.reshape(N)
    print(int(dp.sum() % MOD))

