import sys, heapq

def main():
    data = sys.stdin.buffer.read().split()
    T = int(data[0])
    W = 19
    R = W + 5
    N = 2 * R + 1
    WN = 2 * W + 1
    DX = [1, -1, 0, 0]
    DY = [0, 0, 1, -1]
    INF = float('inf')
    tables = {}
    for P in (1, 2):
        for p in (0, 1):
            for d1 in range(4):
                dist = [INF] * (N * N * 4)
                sx = DX[d1]; sy = DY[d1]
                st = ((sx + R) * N + (sy + R)) * 4 + d1
                dist[st] = 1
                hp = [(1, st)]
                while hp:
                    c, s = heapq.heappop(hp)
                    if c > dist[s]:
                        continue
                    d = s & 3
                    blk = s >> 2
                    xi = blk // N; yi = blk % N
                    x = xi - R; y = yi - R
                    q = (p + x + y) & 1
                    for nd in range(4):
                        nx = xi + DX[nd]; ny = yi + DY[nd]
                        if nx < 0 or nx >= N or ny < 0 or ny >= N:
                            continue
                        w = 1
                        if nd == d:
                            if (q == 0 and d >= 2) or (q == 1 and d < 2):
                                w += P
                        ns = (nx * N + ny) * 4 + nd
                        nc = c + w
                        if nc < dist[ns]:
                            dist[ns] = nc
                            heapq.heappush(hp, (nc, ns))
                for d2 in range(4):
                    arr = [INF] * (WN * WN)
                    for x in range(-W, W + 1):
                        base = ((x + R) * N) * 4
                        for y in range(-W, W + 1):
                            arr[(x + W) * WN + (y + W)] = dist[base + (y + R) * 4 + d2]
                    tables[(P, p, d1, d2)] = arr
    G = 8; M = 8
    out = []
    idx = 1
    for _ in range(T):
