def main():
    data = sys.stdin.buffer.read().split()
    T = int(data[0])
    out = []
    idx = 1

    def cnt_par(lo, hi, q):
        # count t in [lo, hi] with t%2==q
        if hi < lo:
            return 0
        # shift
        first = lo if lo % 2 == q else lo + 1
        if first > hi:
            return 0
        return (hi - first) // 2 + 1

    for _ in range(T):
        K = int(data[idx]); sx = int(data[idx+1]); sy = int(data[idx+2])
        tx = int(data[idx+3]); ty = int(data[idx+4])
        idx += 5

        def tile(x, y):
            i = x // K
            j = y // K
            if (i + j) % 2 == 0:
                k = y - j * K
            else:
                k = x - i * K
            return i, j, k

        def cands(i, j, k):
            bottom = (2 * i + 1, 2 * j)
            top = (2 * i + 1, 2 * j + 2)
            left = (2 * i, 2 * j + 1)
            right = (2 * i + 2, 2 * j + 1)
            if (i + j) % 2 == 0:
                return [(bottom, k), (top, K - 1 - k), (left, 1), (right, 1)]
            else:
                return [(left, k), (right, K - 1 - k), (bottom, 1), (top, 1)]

        def dist(p, q):
            X1, Y1 = p
            X2, Y2 = q
            if K >= 3:
                return max(abs(X1 - X2), abs(Y1 - Y2))
            a1 = (X1 + Y1 - 1) // 2
            b1 = (X1 - Y1 - 1) // 2
            a2 = (X2 + Y2 - 1) // 2
            b2 = (X2 - Y2 - 1) // 2
            da = a2 - a1
            db = b2 - b1
            if da == 0 or db == 0:
                return abs(da) + abs(db)
            right = da > 0
            lo = min(a1, a2)
            hi = max(a1, a2)
            if right:
                qq = 1 if db > 0 else 0
                req = 0
            else:
                qq = 0 if db > 0 else 1
                req = 1
            n = cnt_par(lo, hi - 1, qq)
            w = 1 if (b1 % 2) != req else 0
            d = min(n, (abs(db) + 1 - w) // 2)
            if d < 0:
                d = 0
            return abs(da) + abs(db) - d

        si, sj, sk = tile(sx, sy)
        ti, tj, tk = tile(tx, ty)
        best = None
        if si == ti and sj == tj:
            best = abs(sk - tk)
        cs = cands(si, sj, sk)
        ct = cands(ti, tj, tk)
        for p, c1 in cs:
            for q, c2 in ct:
                v = c1 + c2 + dist(p, q)
                if best is None or v < best:
                    best = v
        out.append(str(best))
    sys.stdout.write("\n".join(out) + "\n")

