    def tile(K, X, Y):
        i = X // K; j = Y // K
        if (i + j) % 2 == 0:
            return i, j, 0, Y - j * K  # H
        else:
            return i, j, 1, X - i * K  # V

    def exits(K, i, j, typ, k):
        a, b = i, j
        bottom = (2*a+1, 2*b); top = (2*a+1, 2*b+2)
        left = (2*a, 2*b+1); right = (2*a+2, 2*b+1)
        if typ == 0:
            return [(bottom, k), (top, K-1-k), (left, 1), (right, 1)]
        else:
            return [(left, k), (right, K-1-k), (bottom, 1), (top, 1)]

    def node2(i, j, typ, k):
        a, b = i, j
        if typ == 0:
            return (2*a+1, 2*b) if k == 0 else (2*a+1, 2*b+2)
        else:
            return (2*a, 2*b+1) if k == 0 else (2*a+2, 2*b+1)

    def cnt(p0, pt, sp):
        # smallest p1>=p0 with parity sp
        p1 = p0 if (p0 - sp) % 2 == 0 else p0 + 1
        v = (pt - p1 + 1)
        if v <= 0:
            return 0
        return v // 2

    def dist2(n1, n2):
        x0, y0 = n1; xt, yt = n2
        p0 = (x0 + y0 - 1) // 2; q0 = (x0 - y0 - 1) // 2
        pt = (xt + yt - 1) // 2; qt = (xt - yt - 1) // 2
        if pt < p0:
            p0, q0, pt, qt = pt, qt, p0, q0
        A = pt - p0; B = qt - q0
        if B >= 0:
            m = min(cnt(p0, pt, 1), cnt(q0, qt, 0))
        else:
            m = min(cnt(p0, pt, 0), cnt(-q0, -qt, 0))
        if m < 0:
            m = 0
        return abs(A) + abs(B) - m

    for _ in range(t):
        K = int(data[idx]); sx = int(data[idx+1]); sy = int(data[idx+2])
        tx = int(data[idx+3]); ty = int(data[idx+4]); idx += 5
        si, sj, st, sk = tile(K, sx, sy)
        ti, tj, tt, tk = tile(K, tx, ty)
        if K == 2:
            n1 = node2(si, sj, st, sk)
            n2 = node2(ti, tj, tt, tk)
            if n1 == n2:
