from collections import deque

def main():
    data = sys.stdin.read().split()
    n, m, k = int(data[0]), int(data[1]), int(data[2])
    edges = []
    for j in range(m):
        u = int(data[3+2*j]) - 1
        v = int(data[4+2*j]) - 1
        edges.append((u, v))
    INF = 10**9

    def mincut(d):
        # nodes: (v,i) i=1..d -> v*d + (i-1); S = n*d, T = n*d+1
        S = n * d
        T = S + 1
        V = T + 1
        graph = [[] for _ in range(V)]
        def add(a, b, c):
            graph[a].append([b, c, len(graph[b])])
            graph[b].append([a, 0, len(graph[a]) - 1])
        def nd(v, i):
            return v * d + (i - 1)
        for v in range(n):
            for i in range(1, d):
                add(nd(v, i+1), nd(v, i), INF)
        for i in range(1, d+1):
            add(nd(0, i), T, INF)
            add(S, nd(n-1, i), INF)
        for (u, v) in edges:
            for i in range(1, d+1):
                add(nd(v, i), nd(u, i), 1)
                if i < d:
                    add(nd(v, i+1), nd(u, i), INF)
        flow = 0
        while True:
            level = [-1] * V
            level[S] = 0
            q = deque([S])
            while q:
                x = q.popleft()
                for to, c, r in graph[x]:
                    if c > 0 and level[to] < 0:
                        level[to] = level[x] + 1
                        q.append(to)
            if level[T] < 0:
                break
            it = [0] * V
            def dfs(x, f):
                if x == T:
                    return f
                while it[x] < len(graph[x]):
                    e = graph[x][it[x]]
                    to, c, r = e
                    if c > 0 and level[to] == level[x] + 1:
                        dd = dfs(to, min(f, c))
                        if dd > 0:
                            e[1] -= dd
                            graph[to][r][1] += dd
                            return dd
                    it[x] += 1
                return 0
            while True:
                f = dfs(S, INF)
                if f == 0:
                    break
                flow += f
                if flow > k:
                    return flow
        return flow

    sys.setrecursionlimit(10000)
    ans = 0
    for d in range(1, n):
        if mincut(d) <= k:
            ans = d
        else:
            break
    print(ans)

