def main():
    data = sys.stdin.read().split()
    n, m, k = int(data[0]), int(data[1]), int(data[2])
    edges = []
    for j in range(m):
        u = int(data[3+2*j])-1; v = int(data[4+2*j])-1
        edges.append((u, v))
    INF = 10**9

    def feasible(d):
        if d == 0:
            return True
        V = n*d + 2
        S = n*d; T = S+1
        g = [[] for _ in range(V)]
        to = []; cap = []
        def add(a, b, c):
            g[a].append(len(to)); to.append(b); cap.append(c)
            g[b].append(len(to)); to.append(a); cap.append(0)
        def node(v, i):  # i in 1..d
            return v*d + (i-1)
        for v in range(n):
            for i in range(1, d):
                add(node(v, i+1), node(v, i), INF)
        for i in range(1, d+1):
            add(node(0, i), T, INF)
        add(S, node(n-1, d), INF)
        for (u, v) in edges:
            for i in range(1, d+1):
                add(node(v, i), node(u, i), 1)
                if i < d:
                    add(node(v, i+1), node(u, i), INF)
        flow = 0
        while flow <= k:
            prev = [-1]*V
            prev[S] = -2
            dq = deque([S])
            found = False
            while dq and not found:
                x = dq.popleft()
                for e in g[x]:
                    if cap[e] > 0:
                        y = to[e]
                        if prev[y] == -1:
                            prev[y] = e
                            if y == T:
                                found = True
                                break
                            dq.append(y)
            if not found:
                break
            # bottleneck
            f = INF
            y = T
            while y != S:
                e = prev[y]
                if cap[e] < f: f = cap[e]
                y = to[e ^ 1]
            if f >= INF:
                return False
            y = T
            while y != S:
                e = prev[y]
                cap[e] -= f
                cap[e ^ 1] += f
                y = to[e ^ 1]
            flow += f
        return flow <= k

    lo, hi = 0, n-1
    while lo < hi:
        mid = (lo+hi+1)//2
        if feasible(mid):
            lo = mid
        else:
            hi = mid-1
    print(lo)

main()

