def main():
    data=sys.stdin.buffer.read().split()
    t=int(data[0]); p=1
    out=[]
    INF=10**9
    maxn=250005
    last=[-INF]*maxn
    for _ in range(t):
        n=int(data[p]); k=int(data[p+1]); p+=2
        A=data[p:p+n]; p+=n
        B=data[p:p+n]; p+=n
        if A==B:
            out.append("Yes"); continue
        A=list(map(int,A)); B=list(map(int,B))
        ok=[False]*n
        # left sweep
        for i in range(n):
            last[A[i]]=i
            if i-last[B[i]]<=k:
                ok[i]=True
        for i in range(n):
            last[A[i]]=-INF
        # right sweep
        for i in range(n-1,-1,-1):
            last[A[i]]=-i  # store negative to reuse array: distance = last_pos - i
            if not ok[i]:
                v=last[B[i]]
                if v!=-INF and v>-INF//2:
                    pos=-v
                    if pos-i<=k:
                        ok[i]=True
        for i in range(n):
            last[A[i]]=-INF
        if not all(ok):
            out.append("No"); continue
        found=False
        for i in range(n):
            if i-last[B[i]]<=k:
                found=True
                break
            last[B[i]]=i
        for i in range(n):
            last[B[i]]=-INF
        out.append("Yes" if found else "No")
    print("\n".join(out))
