    memo = {}

    def g(S, r):
        if len(S) == 0:
            return 0
        if len(S) == 1:
            return 1
        key = (S, r)
        if key in memo:
            return memo[key]
        odd = []
        B = []
        for a in S:
            if (a + r) & 1:
