    n=int(d[0]); A=list(map(int,d[1:1+n]))
    def g(S,P):
        # pending counts
        pc=[0,0]
        for c in P:
            if c&1: pc[1]+=1
            else: pc[0]+=1
        if len(S)==0:
            return max(pc)
        if len(S)==1:
            return max(pc)+1
        best=0
        for b in (0,1):
            S2=[];P2=[]
            for a in S:
                if (a+b)&1:
                    P2.append((a+b-1)>>1)
                else:
                    S2.append((a+b)>>1)
            v=pc[b]+g(S2,P2)
            if v>best: best=v
        return best
    print(g(A,[]))
