    n=int(data[0]); A=list(map(int,data[1:1+n]))
    sys.setrecursionlimit(10000)
    def solve(S,b0,b1):
        if not S:
            return max(b0,b1)
        if len(S)==1:
            return max(b0,b1)+1
        best=0
        for r in (0,1):
            br=b0 if r==0 else b1
            nxt=[]
            nb0=0; nb1=0
            for a in S:
