def main():
    data=sys.stdin.read().split()
    n=int(data[0]); A=list(map(int,data[1:1+n]))
    sys.setrecursionlimit(10000)
    memo={}
    def rec(t,S,forced):
        if not S: return 0
        if len(S)==1: return 1
        r=S[0]&((1<<t)-1)
        key=(t,r,forced)
        if key in memo: return memo[key]
        c=1 if r!=0 else 0
        best=0
        bs=[forced] if forced is not None else [0,1]
        for b in bs:
            D=[];Sp=[]
            for a in S:
                s=b+((a>>t)&1)+c
                if s&1: D.append(a)
                else: Sp.append(a)
            if D:
                s=b+((D[0]>>t)&1)+c
                cd=s>>1
            else:
                cd=0
            cnt1=0
            for a in D:
                cnt1+=(a>>(t+1))&1
            # gain for b': count a in D with (b'+a_{t+1}+cd)&1 == 1
            for bp in (0,1):
                if (bp+cd)&1:
                    g=len(D)-cnt1
