import numpy as np
import sys

def main():
    data = sys.stdin.read().split()
    N = int(data[0]); K = int(data[1]); S = data[2]
    MOD = 998244353
    M = N + 2
    cls = [min(v, v ^ 7) for v in range(8)]
    dp = np.zeros((8, M, M, M), dtype=np.int64)
    dp[0, 1, 0, 0] = 1
    for ch in S:
        if ch == '?':
            opts = [1, 2, 4]
        else:
            opts = [{'A': 1, 'B': 2, 'C': 4}[ch]]
        nd = np.zeros_like(dp)
        for v in range(8):
            old = dp[v]
            if not old.any():
                continue
            for c in opts:
                w = v ^ c
                k = cls[w]
                if k == 0:
                    nd[w, 1:, :, :] += old[:-1, :, :]
                elif k == 1:
                    nd[w, :, 1:, :] += old[:, :-1, :]
                elif k == 2:
                    nd[w, :, :, 1:] += old[:, :, :-1]
                else:
                    nd[w] += old
        nd %= MOD
        dp = nd
    tot = dp.sum(axis=0) % MOD
    idx = np.arange(M)
    a, b, c = np.meshgrid(idx, idx, idx, indexing='ij')
    d = N + 1 - a - b - c
    valid = d >= 0
    pairs = a * (a - 1) // 2 + b * (b - 1) // 2 + c * (c - 1) // 2 + d * (d - 1) // 2
    mask = valid & (pairs >= K)
    ans = int(tot[mask].sum() % MOD)
    print(ans)

