        x = pow(a, d, n)
        if x == 1 or x == n-1: continue
        for _ in range(s-1):
            x = x*x % n
            if x == n-1: break
        else:
            return False
    return True

def rho(n):
    if n % 2 == 0: return 2
    while True:
        c = random.randrange(1, n)
        x = y = random.randrange(2, n)
        d = 1
        while d == 1:
            x = (x*x+c) % n
            y = (y*y+c) % n
            y = (y*y+c) % n
            d = gcd(abs(x-y), n)
        if d != n:
            return d

small_primes = [p for p in range(2, 1000) if all(p % q for q in range(2, int(p**0.5)+1))]

def factor(n):
    fs = []
    for p in small_primes:
        if n % p == 0:
            fs.append(p)
            while n % p == 0:
                n //= p
    if n > 1:
        if is_prime(n):
            fs.append(n)
        else:
            d = rho(n)
            e = n // d
            for x in (d, e):
                if x not in fs:
                    fs.append(x)
    return fs

