def rle(s):
    res = []
    n = len(s)
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        res.append((s[i], j - i))
        i = j
    return res

def normal(s, X, Y):
    runs = rle(s)
    front = 0
    zs = []
    ex = []
    on = []
    b = -1
    for ch, c in runs:
        if ch == '0':
            if zs and on[-1] == 0 and ex[-1] == 0:
                zs[-1] += c
                if zs[-1] % X != 0:
                    b = len(zs) - 1
            else:
                zs.append(c); ex.append(0); on.append(0)
                if c % X != 0:
                    b = len(zs) - 1
        else:
            if not zs:
                front += c
                continue
            z = zs[-1]
            if z < X:
                on[-1] = c
            else:
                k = c // Y
                rem = c % Y
                if k > 0:
                    if b == -1:
                        front += k * Y
                    else:
                        ex[b] += k * Y
                on[-1] = rem
    # render
    out = []
    def add(ch, cnt):
        if cnt <= 0:
            return
        if out and out[-1][0] == ch:
            out[-1][1] += cnt
        else:
            out.append([ch, cnt])
    add('1', front)
    for j in range(len(zs)):
        z = zs[j]
        r = z % X
        add('0', r)
        add('1', ex[j])
        add('0', z - r)
        add('1', on[j])
    return out

