import sys

def normal_form(s, X, Y):
    typ = []   # 0 or 1
    ln = []
    cnt = []
    bstack = []
    start_cnt = 0
    for ch in s:
        if ch == '0':
            if typ and typ[-1] == 0:
                ln[-1] += 1
            else:
                typ.append(0); ln.append(1); cnt.append(0)
        else:
            if typ and typ[-1] == 1:
                ln[-1] += 1
            else:
                # previous zero run becomes non-trailing
                if typ:
                    if ln[-1] % X != 0:
                        bstack.append(len(typ) - 1)
                typ.append(1); ln.append(1); cnt.append(0)
            t = ln[-1]
            if t == Y and len(typ) >= 2:
                w = ln[-2]
                if w >= X:
                    if w % X != 0:
                        # explicit split
                        typ.pop(); ln.pop(); cnt.pop()
                        typ.pop(); ln.pop(); cnt.pop()
                        bstack.pop()
                        r = w % X
                        typ.append(0); ln.append(r); cnt.append(0)
                        bstack.append(len(typ) - 1)
                        typ.append(1); ln.append(Y); cnt.append(0)
                        typ.append(0); ln.append(w - r); cnt.append(0)
                    else:
                        typ.pop(); ln.pop(); cnt.pop()
                        if bstack:
                            cnt[bstack[-1]] += 1
                        else:
                            start_cnt += 1
    parts = []
    if start_cnt:
        parts.append('1' * (start_cnt * Y))
    for i in range(len(typ)):
        if typ[i] == 1:
            parts.append('1' * ln[i])
        else:
            z = ln[i]
            c = cnt[i]
            if c > 0:
                r = z % X
                parts.append('0' * r)
                parts.append('1' * (c * Y))
                parts.append('0' * (z - r))
            else:
                parts.append('0' * z)
    return ''.join(parts)

def main():
    data = sys.stdin.read().split()
    n = int(data[0]); X = int(data[1]); Y = int(data[2])
    S = data[3]; T = data[4]
    if S.count('0') != T.count('0'):
        print("No")
        return
    a = normal_form(S, X, Y)
    b = normal_form(T, X, Y)
    print("Yes" if a == b else "No")

